    ["Healing power increased."] = "Helbredelseskraft øget.",
    ["Healing received reduced by 50% and movement speed reduced by 30%."] = "Modtaget helbredelse reduceret med 50% og bevægelseshastigheden reduceret med 30%.",
    ["Healing."] = "Helbredelse.",
