    ["Amplifie"] = {
        {"^Amplifies% magic% used% against% the% targeted% party% member%,% increasing% damage% taken% from% spells% by% up% to% (.-)% and% healing% spells% by% up% to% (.-)%.% % Lasts% (.-)%.$", {3}, "Forstærker magi brugt mod det udvalgte gruppemedlem og øger skade fra besværgelser med op til ", 1, " og helingsbesværgelser med op til ", 2, ".  Varer ", 3, "."},
    },
    ["An addit"] = {
        {"^An% additional% (.-)%%% of% your% healing% is% transferred% to% your% Beacon% of% Light% target%.$", {}, "En ekstra ", 1, "% af din heling overføres til dit mål for Lysets Fyrtårn."},
    },
    ["An aggre"] = {
        {"^An% aggressive% stance% that% increases% damage% while% you% are% wearing% a% shield% by% (.-)%%% and% increases% block% chance% by% (.-)%%%,% but% reduces% armor% by% (.-)%%% and% threat% generated% by% (.-)%%%.% In% addition%,% you% gain% (.-)%%% increased% Rage% when% your% auto%-attack% damages% an% enemy% not% targeting% you%.%\n%\nWhile% wearing% a% shield% in% Gladiator% Stance%,% you% may% use% all% abilities% that% are% restricted% to% other% stances%.$", {}, "En aggressiv holdning, der øger skaden, mens du bærer et skjold, med ", 1, "% og øger blokchancen med ", 2, "%, men reducerer rustningen med ", 3, "% og den genererede trussel med ", 4, "%. Derudover får du ", 5, "% øget Vrede, når dit autoangreb skader en fjende, der ikke har dig som mål.\n\nMens du bærer et skjold i Gladiatorstilling, må du bruge alle evner, der ellers er begrænset til andre stillinger."},
        {"^An% aggressive% stance%.% Critical% strike% chance% increased% by% (.-)%%% and% all% damage% taken% is% increased% by% (.-)%%%.$", {}, "En aggressiv holdning. Chancen for kritisk slag øges med ", 1, "%, og al modtaget skade øges med ", 2, "%."},
    },
    ["An aimed"] = {
        {"^An% aimed% shot% that% increases% ranged% damage% by% (.-)%.$", {}, "Et sigtet skud, der øger distanceskaden med ", 1, "."},
        {"^An% aimed% shot% that% increases% ranged% damage% by% (.-)%.% Aimed% Shot% shares% its% cooldown% with% Multi%-Shot%.$", {}, "Et sigtet skud, der øger distanceskaden med ", 1, ". Sigtet Skud deler sin nedkøling med Mangeskud."},
    },
    ["An encha"] = {
        {"^An% enchanted% edge% increases% your% chance% to% hit% by% (.-)%%%.% This% has% no% effect% outside% of% Blackfathom% Deeps%.$", {}, "En fortryllet kant øger din chance for at ramme med ", 1, "%. Dette har ingen effekt uden for Den Sorte Afgrund."},
    },
    ["An insta"] = {
        {"^An% instant% attack% that% lashes% the% target%,% causing% (.-)% Shadow% damage%.$", {}, "Et øjeblikkeligt angreb, der pisker målet og forårsager ", 1, " skyggeskade."},
        {"^An% instant% attack% that% lashes% the% target%,% causing% (.-)% Shadow% damage%.$", {}, "Et øjeblikkeligt angreb, der pisker målet og forårsager ", 1, " skyggeskade."},
        {"^An% instant% weapon% attack% that% causes% (.-)%%% of% weapon% damage% to% up% to% (.-)% enemies% within% (.-)% yards%.% % The% Divine% Storm% heals% up% to% 3% party% or% raid% members% totaling% (.-)%%% of% the% damage% caused%.$", {}, "Et øjeblikkeligt våbenangreb, der forårsager ", 1, "% af våbenskaden mod op til ", 2, " fjender inden for ", 3, " meter.  Den Guddommelige Storm heler op til 3 gruppe- eller raidmedlemmer med i alt ", 4, "% af den forårsagede skade."},
        {"^An% instant% strike% that% causes% (.-)%%% weapon% damage% plus% an% additional% (.-)% as% Holy% damage%.$", {}, "Et øjeblikkeligt stød, der forårsager ", 1, "% våbenskade plus yderligere ", 2, " som hellig skade."},
        {"^An% instant% strike% that% causes% (.-)% damage% in% addition% to% your% normal% weapon% damage%.% % Awards% (.-)% combo% %a+%.$", {}, "Et øjeblikkeligt stød, der forårsager ", 1, " skade ud over din normale våbenskade.  Giver ", 2, " ", {"kombinationspoint", "kombinationspoint", 2}, "."},
        {"^An% instant% strike% that% deals% (.-)%%% weapon% damage% %((.-)%%% if% a% Dagger% is% equipped%)% and% causes% the% target% to% take% (.-)%%% increased% Rupture% damage% from% the% Rogue%.% Lasts% (.-)%.% Awards% (.-)% Combo% %a+%.$", {4}, "Et øjeblikkeligt stød, der giver ", 1, "% våbenskade (", 2, "% hvis en Dolk er udstyret), og får målet til at tage ", 3, "% øget Brud-skade fra Skurke. Varer ", 4, ". Giver ", 5, " ", {"Kombinationspoint", "Kombinationspoint", 5}, "."},
        {"^An% instant% shot% that% causes% (.-)% Arcane% damage%.$", {}, "Et øjeblikkeligt skud, der forårsager ", 1, " arkan skade."},
    },
    ["Anara Ch"] = {
        {"^Anara% Chillwind% channels% the% rage% of% Elune% infusing% random% enemies% with% the% weight% of% a% singularity% inflicting% (.-)% Shadow% damage% every% (.-)% sec% for% (.-)%.% Upon% removal%,% a% black% hole% is% formed%.% Enemies% within% the% void% suffer% (.-)% Shadow% damage% every% (.-)% sec% and% are% slowly% pulled% toward% the% center%.$", {3}, "Anara Kuldevind kanaliserer Elunies raseri og indgyder tilfældige fjender tyngden af en singularitet, der forårsager ", 1, " skyggeskade hvert ", 2, " sek. i ", 3, ". Når den fjernes, dannes et sort hul. Fjender inden for tomrummet lider ", 4, " skyggeskade hvert ", 5, " sek. og trækkes langsomt mod centrum."},
        {"^Anara% Chillwind% hails% the% umbral% night% creating% a% singularity% at% her% location% that% pulls% in% nearby% enemies% for% (.-)%.% The% intense% gravity% well% inflicts% (.-)% Shadow% damage% and% any% targets% that% fall% into% the% singularity% are% instantly% killed%.$", {1}, "Anara Kuldevind hilser den skyggefulde nat og skaber en singularitet på sin placering, der trækker nærliggende fjender til sig i ", 1, ". Den intense tyngdekraftsbrønd forårsager ", 2, " skyggeskade, og alle mål, der falder ind i singulariteten, dræbes øjeblikkeligt."},
        {"^Anara% Chillwind% channels% the% grace% of% Elune%,% infusing% random% enemies% with% the% might% of% a% star% and% inflicting% (.-)% Arcane% damage% every% (.-)% sec% for% (.-)%.% Upon% removal%,% a% collapsing% star% is% formed%.% Enemies% within% the% star% suffer% (.-)% Arcane% damage% every% (.-)% sec% and% have% their% movement% speed% reduced% by% (.-)%%%.$", {3}, "Anara Kuldevind kanaliserer Elunies nåde, indgyder tilfældige fjender stjernens styrke og forårsager ", 1, " arkan skade hvert ", 2, " sek. i ", 3, ". Når den fjernes, dannes en kollapsende stjerne. Fjender inden for stjernen lider ", 4, " arkan skade hvert ", 5, " sek. og får deres bevægelseshastighed reduceret med ", 6, "%."},
    },
    ["Anara ca"] = {
        {"^Anara% calls% down% stars% at% random% players%'% locations% every% (.-)% sec% for% (.-)%.% Each% star% inflicts% (.-)% Arcane% damage% to% all% players% within% (.-)% yds% of% the% impact%.$", {2}, "Anara kalder stjerner ned over tilfældige spilleres placeringer hvert ", 1, " sek. i ", 2, ". Hver stjerne forårsager ", 3, " arkan skade til alle spillere inden for ", 4, " meter fra nedslaget."},
    },
    ["Angers a"] = {
        {"^Angers% a% target%,% drawing% its% attention% and% lowering% its% armor% value% by% (.-)%.$", {}, "Ophidser et mål, trækker dets opmærksomhed til sig og sænker dets rustningsværdi med ", 1, "."},
    },
    ["Animate "] = {
        {"^Animate% (.-)% skeletons% that% attack% your% current% target% with% a% mace%,% sword%,% and% axe%,% reducing% the% target%'s% attack% speed%,% attack% power%,% and% armor% respectively%.$", {}, "Animer ", 1, " skeletter, der angriber dit nuværende mål med en kølle, et sværd og en økse, og reducerer henholdsvis målets angrebshastighed, angrebskraft og rustning."},
