    ["Anti-mag"] = {
        {"^Anti%-magic% energy% will% burn% (.-)% of% the% attacker%'s% Mana%,% causing% 1% Shadow% damage% for% each% point% of% Mana% burned%.$", {}, "Anti-magisk energi vil brænde ", 1, " af angriberens Mana og forårsage 1 skyggeskade for hver peg Mana, der brændes."},
        {"^Anti%-magic% energy% will% burn% (.-)% of% the% attacker%'s% Mana%,% causing% 1% Shadow% damage% for% each% point% of% Mana% burned%.$", {}, "Anti-magisk energi vil brænde ", 1, " af angriberens Mana og forårsage 1 skyggeskade for hver peg Mana, der brændes."},
        {"^Anti%-magic% energy% will% burn% (.-)% of% the% attacker%'s% Mana%,% causing% 1% Shadow% damage% for% each% point% of% Mana% burned%.$", {}, "Anti-magisk energi vil brænde ", 1, " af angriberens Mana og forårsage 1 skyggeskade for hver peg Mana, der brændes."},
        {"^Anti%-magic% energy% will% burn% (.-)% of% the% attacker%'s% Mana%,% causing% 1% Shadow% damage% for% each% point% of% Mana% burned%.$", {}, "Anti-magisk energi vil brænde ", 1, " af angriberens Mana og forårsage 1 skyggeskade for hver peg Mana, der brændes."},
        {"^Anti%-magic% energy% will% burn% (.-)% of% the% attacker%'s% Mana%,% causing% 1% Shadow% damage% for% each% point% of% Mana% burned%.$", {}, "Anti-magisk energi vil brænde ", 1, " af angriberens Mana og forårsage 1 skyggeskade for hver peg Mana, der brændes."},
