    ["Anvilmar"] = {
        {"^Anvilmar% causes% the% target%'s% skin% to% become% like% stone%,% reducing% attack% speed% and% casting% speed% by% (.-)%%% but% also% making% them% immune% to% Poison% and% Bleed% effects% for% (.-)%.$", {2}, "Ambolmar får målets hud til at blive som sten, reducerer angrebshastighed og besværgelseshastighed med ", 1, "%, men gør dem også immune over for Gift- og Bløde-effekter i ", 2, "."},
    },
    ["Any atta"] = {
        {"^Any% attack% which% would% otherwise% kill% you% will% instead% reduce% you% to% 10%%% of% your% maximum% health%.% In% addition%,% all% damage% taken% will% be% reduced% by% up% to% (.-)%%% for% (.-)%.% % This% effect% cannot% occur% more% than% once% per% minute%.$", {2}, "Ethvert angreb, der ellers ville dræbe dig, reducerer i stedet dit maksimale helbred til 10%. Derudover reduceres al modtaget skade med op til ", 1, "% i ", 2, ".  Denne effekt kan kun ske én gang i minuttet."},
    },
    ["Any dama"] = {
        {"^Any% damage% from% an% Undead% attacker% which% would% otherwise% kill% you% will% instead% reduce% you% to% (.-)%%% of% your% maximum% health% %(or% your% current% health%,% whichever% is% lower%)%.% In% addition%,% all% damage% taken% from% Undead% will% be% reduced% by% (.-)%%% for% (.-)%.% % This% effect% cannot% occur% more% than% once% per% minute%.$", {3}, "Al skade fra en Udøde angriber, der ellers ville dræbe dig, reducerer i stedet dit helbred til ", 1, "% af dit maksimale helbred (eller dit nuværende helbred, alt efter hvad der er lavest). Derudover reduceres al skade fra Udøde med ", 2, "% i ", 3, ".  Denne effekt kan kun ske én gang i minuttet."},
    },
    ["Any exce"] = {
        {"^Any% excess% healing% you% deal% to% yourself% % is% converted% into% a% shield% that% absorbs% damage%.% This% shield% can% absorb% up% to% (.-)%%% of% your% maximum% health%,% and% stacks% from% multiple% heals%.$", {}, "Al overskydende heling, du giver dig selv,  omdannes til et skjold, der absorberer skade. Dette skjold kan absorbere op til ", 1, "% af dit maksimale helbred, og det stabler fra flere helinger."},
    },
    ["Any time"] = {
        {"^Any% time% you% score% 2% spell% criticals% in% a% row% using% using% Fireball%,% Fire% Blast%,% Scorch%,% Living% Bomb%,% or% Frostfire% Bolt%,% you% have% a% chance% the% next% Pyroblast% spell% cast% within% (.-)% will% be% instant% cast%.$", {1}, "Hver gang du rammer 2 kritiske besværgelser i træk med Ildkugle, Ildsprængning, Forbrænding, Levende Bombe eller Frostildsbolt, har du en chance for, at den næste Pyrosprængning, der besværges inden for ", 1, ", bliver en øjeblikkelig besværgelse."},
    },
    ["Applies "] = {
        {"^Applies% an% aura% that% causes% players% to% explode% when% it% expires%,% dealing% (.-)% Shadow% damage% to% all% nearby% players% and% leaves% a% damaging% pool%.$", {}, "Påfører en aura, der får spillere til at eksplodere, når den udløber, og forvolder ", 1, " Skyggeskade til alle nærliggende spillere og efterlader en skadelig pyt."},
        {"^Applies% an% aura% that% will% detonate% if% not% reapplied% or% removed% within% (.-)% seconds%.% Dissipates% after% (.-)% seconds%.$", {}, "Påfører en aura, der detonerer, hvis den ikke genpåføres eller fjernes inden for ", 1, " sekunder. Spredes efter ", 2, " sekunder."},
        {"^Applies% your% Vampiric% Embrace% talent% to% your% target%,% causes% (.-)% Shadow% damage% over% (.-)% to% your% target%,% and% causes% all% party% members% to% gain% mana% equal% to% (.-)%%% of% any% Shadow% spell% damage% you% deal% to% the% target%.$", {2}, "Påfører dit Vampyrisk Omfavnelse-talent på dit mål, forvolder ", 1, " Skyggeskade over ", 2, " til dit mål, og får alle gruppemedlemmer til at få mana svarende til ", 3, "% af al skade fra Skyggebesværgelser, du forvolder målet."},
        {"^Applies% a% powerful% curse% to% the% target%,% dealing% (.-)% Shadow% damage% after% (.-)%.$", {2}, "Påfører målet en kraftig forbandelse, der forvolder ", 1, " Skyggeskade efter ", 2, "."},
        {"^Applies% Light%'s% Vigil% to% the% target% for% (.-)%.% Your% next% Holy% Shock% cast% on% them% triggers% no% cooldown% and% causes% enemy% targets% to% suffer% (.-)% Holy% damage% and% refund% (.-)%%% of% Light%'s% Vigil%'s% Mana% cost%,% or% allied% targets% to% heal% their% party% for% (.-)%.% You% may% only% have% one% Light%'s% Vigil% active% per% party%.$", {1}, "Påfører Lets Vagt på målet i ", 1, ". Din næste besværgelse af Hellig Chok på dem udløser ingen nedkøling og får fjendtlige mål til at lide ", 2, " Hellig skade og tilbagefører ", 3, "% af Lets Vagts manaomkostning, eller får allierede mål til at helbrede deres gruppe for ", 4, ". Du kan kun have én Lets Vagt aktiv pr. gruppe."},
        {"^Applies% Light%'s% Vigil% to% the% target% for% (.-)%.% Your% next% Holy% Shock% cast% on% them% triggers% no% cooldown% and% causes% enemy% targets% to% suffer% (.-)% Holy% damage% and% refund% (.-)%%% of% Light%'s% Vigil%'s% Mana% cost%,% or% allied% targets% to% heal% their% party% for% (.-)%.% You% may% only% have% one% Light%'s% Vigil% active% per% party%.$", {1}, "Påfører Lets Vagt på målet i ", 1, ". Din næste besværgelse af Hellig Chok på dem udløser ingen nedkøling og får fjendtlige mål til at lide ", 2, " Hellig skade og tilbagefører ", 3, "% af Lets Vagts manaomkostning, eller får allierede mål til at helbrede deres gruppe for ", 4, ". Du kan kun have én Lets Vagt aktiv pr. gruppe."},
        {"^Applies% Light%'s% Vigil% to% the% target% for% (.-)%.% Your% next% Holy% Shock% cast% on% them% triggers% no% cooldown% and% causes% enemy% targets% to% suffer% (.-)% Holy% damage% and% refund% (.-)%%% of% Light%'s% Vigil%'s% Mana% cost%,% or% allied% targets% to% heal% their% party% for% (.-)%.% You% may% only% have% one% Light%'s% Vigil% active% per% party%.$", {1}, "Påfører Lets Vagt på målet i ", 1, ". Din næste besværgelse af Hellig Chok på dem udløser ingen nedkøling og får fjendtlige mål til at lide ", 2, " Hellig skade og tilbagefører ", 3, "% af Lets Vagts manaomkostning, eller får allierede mål til at helbrede deres gruppe for ", 4, ". Du kan kun have én Lets Vagt aktiv pr. gruppe."},
        {"^Applies% an% aura% that% heals% for% (.-)%%% of% maximum% health% every% (.-)% for% (.-)% sec%.$", {}, "Påfører en aura, der helbreder ", 1, "% af maksimalt liv hvert ", 2, " i ", 3, " sek."},
