    ["Construc"] = {
        {"^Constructs% a% mana% well% that% allows% you% and% others% sitting% nearby% to% regenerate% 10% Mana% every% 5% sec%,% mutually% exclusive% with% Blessing% of% Wisdom%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {1}, "Konstruerer en manabrønd, der gør det muligt for dig og andre, der sidder i nærheden, at regenerere 10 Mana hver 5 sek., og den kan ikke kombineres med Velsignelse af Visdom.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 1, "."},
        {"^Constructs% a% mana% well% that% allows% you% and% others% sitting% nearby% to% regenerate% 15% Mana% every% 5% sec%,% mutually% exclusive% with% Blessing% of% Wisdom%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {1}, "Konstruerer en manabrønd, der gør det muligt for dig og andre, der sidder i nærheden, at regenerere 15 Mana hver 5 sek., og den kan ikke kombineres med Velsignelse af Visdom.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 1, "."},
        {"^Constructs% a% mana% well% that% allows% you% and% others% sitting% nearby% to% regenerate% 20% Mana% every% 5% sec%,% mutually% exclusive% with% Blessing% of% Wisdom%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {1}, "Konstruerer en manabrønd, der gør det muligt for dig og andre, der sidder i nærheden, at regenerere 20 Mana hver 5 sek., og den kan ikke kombineres med Velsignelse af Visdom.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 1, "."},
        {"^Constructs% a% mana% well% that% allows% you% and% others% sitting% nearby% to% regenerate% 24% Mana% every% 5% sec%,% mutually% exclusive% with% Blessing% of% Wisdom%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {1}, "Konstruerer en manabrønd, der gør det muligt for dig og andre, der sidder i nærheden, at regenerere 24 Mana hver 5 sek., og den kan ikke kombineres med Velsignelse af Visdom.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 1, "."},
        {"^Constructs% a% sharpening% wheel% that% grants% you% and% others% sitting% nearby% 11% increased% Strength%,% mutually% exclusive% with% Strength% of% Earth% Totem%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {1}, "Konstruerer et slibehjul, der giver dig og andre, der sidder i nærheden, 11 øget Styrke, og den kan ikke kombineres med Jordtotemets Styrke.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 1, "."},
        {"^Constructs% a% sharpening% wheel% that% grants% you% and% others% sitting% nearby% 20% increased% Strength%,% mutually% exclusive% with% Strength% of% Earth% Totem%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {1}, "Konstruerer et slibehjul, der giver dig og andre, der sidder i nærheden, 20 øget Styrke, og den kan ikke kombineres med Jordtotemets Styrke.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 1, "."},
        {"^Constructs% a% sharpening% wheel% that% grants% you% and% others% sitting% nearby% 6% increased% Strength%,% mutually% exclusive% with% Strength% of% Earth% Totem%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {1}, "Konstruerer et slibehjul, der giver dig og andre, der sidder i nærheden, 6 øget Styrke, og den kan ikke kombineres med Jordtotemets Styrke.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 1, "."},
        {"^Constructs% a% mana% well% that% allows% you% and% others% sitting% nearby% to% regenerate% (.-)% Mana% every% 5% sec%,% mutually% exclusive% with% Blessing% of% Wisdom%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {2}, "Konstruerer en manabrønd, der gør det muligt for dig og andre, der sidder i nærheden, at regenerere ", 1, " Mana hver 5 sek., og den kan ikke kombineres med Velsignelse af Visdom.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 2, "."},
        {"^Constructs% a% sharpening% wheel% that% grants% you% and% others% sitting% nearby% (.-)% increased% Strength%,% mutually% exclusive% with% Strength% of% Earth% Totem%.%\n%\nRequires% a% Campfire% nearby%.% All% camping% features% share% a% cooldown% of% (.-)%.$", {2}, "Konstruerer et slibehjul, der giver dig og andre, der sidder i nærheden, ", 1, " øget Styrke, og den kan ikke kombineres med Jordtotemets Styrke.\n\nKræver et Lejrbål i nærheden. Alle lejrfunktioner deler en genopladning på ", 2, "."},
