    ["Consume "] = {
        {"^Consume% your% Strands% of% Fate%,% increasing% your% Strength% by% (.-)% per% stack% for% (.-)%,% and% causing% your% next% Strike% against% a% non%-player% controlled% target% to% apply% Serpent% Sting%.% Lasts% (.-)% secs% for% every% stack% consumed% and% cannot% be% refreshed%.$", {2}, "Fortær dine Skæbnetråde, øger din Styrke med ", 1, " pr. stak i ", 2, ", og får dit næste Slag mod et mål, der ikke styres af en spiller, til at påføre Slangebrod. Varer ", 3, " sek. for hvert fortæret stak og kan ikke genopfriskes."},
        {"^Consume% a% delicious%,% hand%-picked% apple% to% restore% (.-)%%% of% your% maximum% health% instantly% and% another% (.-)%%% every% (.-)% sec% for% (.-)%.$", {4}, "Fortær et lækkert, håndplukket æble for straks at genoprette ", 1, "% af dit maksimale helbred og yderligere ", 2, "% hvert ", 3, " sek. i ", 4, "."},
    },
    ["Consumes"] = {
        {"^Consumes% all% applications% of% Frenzy% from% your% pet%,% increasing% your% ranged% attack% speed% by% (.-)%%% and% granting% (.-)% Focus% to% your% pet% for% each% application% of% Frenzy% consumed%.% Lasts% (.-)%.%\n%\nYour% pet% gains% Frenzy% each% time% it% uses% a% Basic% Attack%,% increasing% its% melee% attack% speed% by% (.-)%%% for% (.-)%,% stacking% up% to% (.-)% times%.$", {3, 5}, "Fortærer alle stable af Raseri fra dit kæledyr og øger din distance-angrebshastighed med ", 1, "% og giver dit kæledyr ", 2, " Fokus for hver stabel af Raseri, der fortæres. Varer ", 3, ".\n\nDit kæledyr får Raseri, hver gang det bruger et Simpelt Angreb, og øger dets nærkamps-angrebshastighed med ", 4, "% i ", 5, " og kan stable op til ", 6, " gange."},
        {"^Consumes% an% enemy% in% flames%,% burning% it% and% inflicting% additional% Fire% damage% every% (.-)% sec%.% over% (.-)%.$", {2}, "Fortærer en fjende i flammer, brænder den og påfører yderligere Ildskade hvert ", 1, " sek. over ", 2, "."},
        {"^Consumes% the% target% in% holy% flames% that% cause% (.-)% Holy% damage% and% an% additional% (.-)% Holy% damage% every% (.-)% sec% for% (.-)%.$", {4}, "Fortærer målet i hellige flammer, der forårsager ", 1, " Helligskade og yderligere ", 2, " Helligskade hvert ", 3, " sek. i ", 4, "."},
        {"^Consumes% the% enemy% in% holy% flames% that% cause% (.-)% Holy% damage% and% an% additional% (.-)% Holy% damage% over% (.-)%.$", {3}, "Fortærer fjenden i hellige flammer, der forårsager ", 1, " Helligskade og yderligere ", 2, " Helligskade over ", 3, "."},
