    ["Draws on"] = {
        {"^Draws% on% the% soul% of% the% party% member% to% shield% them%,% absorbing% (.-)% damage%.% % Lasts% (.-)%.% % While% the% shield% holds%,% spellcasting% will% not% be% interrupted% by% damage%.% % Once% shielded%,% the% target% cannot% be% shielded% again% for% (.-)%.$", {2, 3}, "Trækker på gruppemedlemmets sjæl for at skjolde dem med et absorberende skjold på ", 1, " skade.  Varer ", 2, ".  Mens skjoldet holder, afbrydes besværgelsesstøbning ikke af skade.  Når de først er skjoldet, kan de ikke skjoldes igen i ", 3, "."},
        {"^Draws% on% the% soul% of% the% party% member% to% shield% them%,% absorbing% (.-)% damage%.% % Lasts% (.-)%.% % While% the% shield% holds%,% spellcasting% will% not% be% interrupted% by% damage%.% % Once% shielded%,% the% target% cannot% be% shielded% again% for% (.-)%.$", {2, 3}, "Trækker på gruppemedlemmets sjæl for at skjolde dem med et absorberende skjold på ", 1, " skade.  Varer ", 2, ".  Mens skjoldet holder, afbrydes besværgelsesstøbning ikke af skade.  Når de først er skjoldet, kan de ikke skjoldes igen i ", 3, "."},
        {"^Draws% on% the% soul% of% the% target% to% shield% them%,% absorbing% (.-)% damage%.% % Lasts% (.-)%.% % While% the% shield% holds%,% spellcasting% will% not% be% interrupted% by% damage%.% % Once% shielded%,% the% target% cannot% be% shielded% again% for% (.-)%.$", {2, 3}, "Trækker på målets sjæl for at skjolde dem med et absorberende skjold på ", 1, " skade.  Varer ", 2, ".  Mens skjoldet holder, afbrydes besværgelsesstøbning ikke af skade.  Når de først er skjoldet, kan de ikke skjoldes igen i ", 3, "."},
    },
    ["Drink to"] = {
        {"^Drink% to% improve% your% spatial% awareness% which% allows% you% to% see% hidden% Mining% and% Herbalism% gathering% nodes% for% (.-)%.%\n%\nThis% effect% persists% through% death%.$", {1}, "Drik for at forbedre din rumlige opmærksomhed, så du kan se skjulte Minedrift- og Urtekundskab-indsamlingspunkter i ", 1, ".\n\nDenne effekt består gennem døden."},
        {"^Drink% to% slightly% increase% your% stealth% detection%.% While% you% are% not% moving% for% (.-)% sec%,% nearby% moving% stealthed% enemies% may% reveal% a% heat% trail%.% Lasts% for% (.-)%.$", {2}, "Drik for at øge din snigskjulsopdagelse en smule. Mens du ikke bevæger dig i ", 1, " sek., kan nærliggende bevægende snigskjulte fjender afsløre et varmespor. Varer i ", 2, "."},
