        {"^Drink% to% increase% spell% damage% by% up% to% (.-)%.% Lasts% for% (.-)%.$", {2}, "Drik for at øge besværgelsesskade med op til ", 1, ". Varer i ", 2, "."},
        {"^Drink% to% increase% your% Intellect% by% (.-)% and% chance% to% critically% hit% by% (.-)%%%.% Lasts% for% (.-)%.$", {3}, "Drik for at øge dit Intellekt med ", 1, " og chancen for kritisk træf med ", 2, "%. Varer i ", 3, "."},
        {"^Drink% to% increase% your% Intellect% by% (.-)%.% Lasts% for% (.-)%.$", {2}, "Drik for at øge dit Intellekt med ", 1, ". Varer i ", 2, "."},
        {"^Drink% to% increase% your% Strength% by% (.-)% and% chance% to% critically% hit% by% (.-)%%%.% Lasts% for% (.-)%.$", {3}, "Drik for at øge din Styrke med ", 1, " og chancen for kritisk træf med ", 2, "%. Varer i ", 3, "."},
