    ["Empowere"] = {
        {"^Empowered% by% the% brave% discoverers% that% preceded% you%,% experience% gains% increased% by% (.-)%%%,% and% gold% earned% from% quests% also% increases% by% (.-)%%%.$", {}, "Styrket af de modige opdagere, der gik forud for dig: erfaring øges med ", 1, "%, og guld tjent fra opgaver øges også med ", 2, "%."},
