    ["Encases "] = {
        {"^Encases% the% target% in% sticky% webs% rendering% them% unable% to% move% for% (.-)%.$", {1}, "Indkapsler målet i klæbrige spind, så det ikke kan bevæge sig i ", 1, "."},
