    ["Fills yo"] = {
        {"^Fills% you% with% divine% fury% for% (.-)%,% causing% melee% attacks% to% deal% an% additional% (.-)% Holy% damage%.% While% a% shield% is% equipped%,% each% attack% also% grants% an% absorb% shield% equal% to% (.-)%%% of% the% Holy% damage% dealt%.% Only% one% Seal% can% be% active% on% the% Paladin% at% any% one% time%.%\n%\nUnleashing% this% Seal%'s% energy% inflicts% (.-)% Holy% damage% to% an% enemy% and% taunts% the% target% to% attack% you% for% (.-)%.$", {1, 5}, "Fylder dig med guddommelig raseri i ", 1, ", hvilket får nærkampsangreb til at forvolde et ekstra ", 2, " Helligskade. Mens et skjold er udstyret, giver hvert angreb også et absorberingsskjold svarende til ", 3, "% af den forvoldte Helligskade. Kun ét Segl kan være aktivt på Paladinen ad gangen.\n\nNår dette Segls energi udløses, forvolder den ", 4, " Helligskade mod en fjende og provokerer målet til at angribe dig i ", 5, "."},
        {"^Fills% you% with% divine% fury% for% (.-)%,% causing% melee% attacks% to% inflict% an% additional% (.-)% Holy% damage%.% While% a% shield% is% equipped%,% each% attack% also% grants% an% absorb% shield% equal% to% (.-)%%% of% the% Holy% damage% dealt%.% Only% one% Seal% can% be% active% on% the% Paladin% at% any% one% time%.%\n%\nUnleashing% this% Seal%'s% energy% inflicts% (.-)% Holy% damage% to% an% enemy% and% taunts% the% target% to% attack% you% for% (.-)%.$", {1, 5}, "Fylder dig med guddommelig raseri i ", 1, ", hvilket får nærkampsangreb til at forvolde et ekstra ", 2, " Helligskade. Mens et skjold er udstyret, giver hvert angreb også et absorberingsskjold svarende til ", 3, "% af den forvoldte Helligskade. Kun ét Segl kan være aktivt på Paladinen ad gangen.\n\nNår dette Segls energi udløses, forvolder den ", 4, " Helligskade mod en fjende og provokerer målet til at angribe dig i ", 5, "."},
        {"^Fills% you% with% holy% spirit% for% (.-)%,% causing% each% of% your% melee% attacks% to% deal% (.-)%%% weapon% damage% to% your% target%,% but% you% lose% health% equal% to% (.-)%%% of% the% damage% inflicted%.% While% this% seal% is% active%,% your% party% and% raid% members% within% (.-)% yards% each% gain% mana% equal% to% (.-)%%% of% damage% you% take% from% this% seal%.%\n%\n%\nUnleashing% this% Seal%'s% energy% will% judge% an% enemy%,% instantly% causing% (.-)%%% weapon% damage% at% the% cost% of% health% equal% to% (.-)%%% of% the% damage% inflicted%.%\n%\nThis% ability%'s% Seal% and% Judgement% benefit% from% talents% and% effects% that% modify% the% Seal% or% Judgement% of% Seal% of% Righteousness%.$", {1}, "Fylder dig med helligånd i ", 1, ", hvilket får hvert af dine nærkampsangreb til at forvolde ", 2, "% våbenskade til dit mål, men du mister helbred svarende til ", 3, "% af den forvoldte skade. Mens dette segl er aktivt, får dine gruppe- og togtmedlemmer inden for ", 4, " meter hver mana svarende til ", 5, "% af den skade, du tager fra dette segl.\n\n\nNår dette Segls energi udløses, dømmer den en fjende og forvolder øjeblikkeligt ", 6, "% våbenskade til prisen af helbred svarende til ", 3, "% af den forvoldte skade.\n\nDenne evnes Segl og Dom drager fordel af talenter og effekter, der ændrer Segl eller Dom for Retfærdighedens Segl."},
    },
    ["Finds a "] = {
        {"^Finds% a% weak% spot% which% causes% the% target% to% take% (.-)% more% damage% from% physical% hits% for% (.-)$", {2}, "Finder et svagt punkt, der får målet til at tage ", 1, " mere skade fra fysiske slag i ", 2},
    },
    ["Finishes"] = {
        {"^Finishes% the% remaining% cooldown% on% your% Judgement% ability% and% reduces% the% Mana% cost% of% your% next% Judgement% by% (.-)%%%.$", {}, "Afslutter den resterende genopladning på din Dom-evne og reducerer Manaomkostningen for din næste Dom med ", 1, "%."},
    },
    ["Finishin"] = {
        {"^Finishing% move% that% causes% damage% over% time%,% increased% by% your% Attack% Power%.% % Lasts% longer% per% combo% point%:%\n% % % 1% point% % %:% (.-)% damage% over% 8% secs%\n% % % 2% points%:% (.-)% damage% over% 10% secs%\n% % % 3% points%:% (.-)% damage% over% 12% secs%\n% % % 4% points%:% (.-)% damage% over% 14% secs%\n% % % 5% points%:% (.-)% damage% over% 16% secs$", {}, "Afslutningstræk, der forvolder skade over tid, forøget af din Angrebskraft.  Varer længere pr. kombinationspunkt:\n   1 punkt  : ", 1, " skade over 8 sek.\n   2 punkter: ", 2, " skade over 10 sek.\n   3 punkter: ", 3, " skade over 12 sek.\n   4 punkter: ", 4, " skade over 14 sek.\n   5 punkter: ", 5, " skade over 16 sek."},
        {"^Finishing% move% that% causes% damage% over% time%.% % Damage% increases% per% combo% point% and% by% your% Attack% Power%:%\n% % % 1% point% % %:% (.-)% damage% over% (.-)%.%\n% % % 2% points%:% (.-)% damage% over% (.-)%.%\n% % % 3% points%:% (.-)% damage% over% (.-)%.%\n% % % 4% points%:% (.-)% damage% over% (.-)%.%\n% % % 5% points%:% (.-)% damage% over% (.-)%.$", {2, 4, 6, 8, 10}, "Afslutningstræk, der forvolder skade over tid.  Skaden øges pr. kombinationspunkt og af din Angrebskraft:\n   1 punkt  : ", 1, " skade over ", 2, ".\n   2 punkter: ", 3, " skade over ", 2, ".\n   3 punkter: ", 5, " skade over ", 2, ".\n   4 punkter: ", 7, " skade over ", 2, ".\n   5 punkter: ", 9, " skade over ", 2, "."},
        {"^Finishing% move% that% marks% the% target%,% storing% a% portion% of% the% damage% dealt% by% your% attacks% per% Combo% Point%.% After% (.-)%,% the% stored% damage% is% dealt%,% up% to% a% maximum% increased% by% Attack% Power% and% Critical% Strike% chance%:%\n% % % 1% point% % %:% (.-)%%% stored%,% (.-)% damage% cap%.%\n% % % 2% points%:% (.-)%%% stored%,% (.-)% damage% cap%.%\n% % % 3% points%:% (.-)%%% stored%,% (.-)% damage% cap%.%\n% % % 4% points%:% (.-)%%% stored%,% (.-)% damage% cap%.%\n% % % 5% points%:% (.-)%%% stored%,% (.-)% damage% cap%.$", {1}, "Afslutningstræk, der markerer målet og lagrer en del af den skade, dine angreb forvolder pr. kombinationspunkt. Efter ", 1, " udløses den lagrede skade, op til et maksimum, der øges af Angrebskraft og chancen for Kritisk Slag:\n   1 punkt  : ", 2, "% lagret, ", 3, " skadeloft.\n   2 punkter: ", 4, "% lagret, ", 5, " skadeloft.\n   3 punkter: ", 6, "% lagret, ", 7, " skadeloft.\n   4 punkter: ", 8, "% lagret, ", 9, " skadeloft.\n   5 punkter: ", 10, "% lagret, ", 11, " skadeloft."},
        {"^Finishing% move% that% marks% the% target%,% storing% a% portion% of% the% damage% dealt% by% your% attacks% per% Combo% Point%.% After% (.-)%,% the% stored% damage% is% dealt%,% up% to% a% maximum% increased% by% Attack% Power% and% Critical% Strike% chance%:%\n% % % 1% point% % %:% (.-)%%% stored%,% (.-)% cap% before% critical% strike%.%\n% % % 2% points%:% (.-)%%% stored%,% (.-)% damage% cap%.%\n% % % 3% points%:% (.-)%%% stored%,% (.-)% damage% cap%.%\n% % % 4% points%:% (.-)%%% stored%,% (.-)% damage% cap%.%\n% % % 5% points%:% (.-)%%% stored%,% (.-)% damage% cap%.$", {1}, "Afslutningstræk, der markerer målet og lagrer en del af den skade, dine angreb forvolder pr. kombinationspunkt. Efter ", 1, " udløses den lagrede skade, op til et maksimum, der øges af Angrebskraft og chancen for Kritisk Slag:\n   1 punkt  : ", 2, "% lagret, ", 3, " loft før kritisk slag.\n   2 punkter: ", 4, "% lagret, ", 5, " skadeloft.\n   3 punkter: ", 6, "% lagret, ", 7, " skadeloft.\n   4 punkter: ", 8, "% lagret, ", 9, " skadeloft.\n   5 punkter: ", 10, "% lagret, ", 11, " skadeloft."},
        {"^Finishing% move% that% marks% the% target%,% storing% a% portion% of% the% damage% dealt% by% your% attacks% per% Combo% Point%.% After% (.-)%,% the% stored% damage% is% dealt%,% up% to% a% maximum% increased% by% Attack% Power%:%\n% % % 1% point% % %:% (.-)%%% of% damage% stored%,% (.-)%%% Attack% Power% max%.%\n% % % 2% points%:% (.-)%%% of% damage% stored%,% (.-)%%% of% Attack% Power% max%.%\n% % % 3% points%:% (.-)%%% of% damage% stored%,% (.-)%%% of% Attack% Power% max%.%\n% % % 4% points%:% (.-)%%% of% damage% stored%,% (.-)%%% of% Attack% Power% max%.%\n% % % 5% points%:% (.-)%%% of% damage% stored%,% (.-)%%% of% Attack% Power% max%.$", {1}, "Afslutningstræk, der markerer målet og lagrer en del af den skade, dine angreb forvolder pr. kombinationspunkt. Efter ", 1, " udløses den lagrede skade, op til et maksimum, der øges af Angrebskraft:\n   1 punkt  : ", 2, "% af skaden lagret, ", 3, "% Angrebskraft maks.\n   2 punkter: ", 4, "% af skaden lagret, ", 5, "% af Angrebskraft maks.\n   3 punkter: ", 6, "% af skaden lagret, ", 7, "% af Angrebskraft maks.\n   4 punkter: ", 8, "% af skaden lagret, ", 9, "% af Angrebskraft maks.\n   5 punkter: ", 10, "% af skaden lagret, ", 11, "% af Angrebskraft maks."},
        {"^Finishing% move% that% causes% damage% over% time%.% % Damage% increases% per% combo% point%:%\n% % % 1% point% % %:% 228% damage% over% (.-)%.%\n% % % 2% points%:% 354% damage% over% (.-)%.%\n% % % 3% points%:% 480% damage% over% (.-)%.%\n% % % 4% points%:% 606% damage% over% (.-)%.%\n% % % 5% points%:% 732% damage% over% (.-)%.$", {1, 2, 3, 4, 5}, "Afslutningstræk, der forvolder skade over tid.  Skaden øges pr. kombinationspunkt:\n   1 punkt  : 228 skade over ", 1, ".\n   2 punkter: 354 skade over ", 1, ".\n   3 punkter: 480 skade over ", 1, ".\n   4 punkter: 606 skade over ", 1, ".\n   5 punkter: 732 skade over ", 1, "."},
