    ["Gives "] = {
        {"^Gives% (.-)% additional% intellect% to% party% members% within% (.-)% yards%.$", {}, "Giver ", 1, " ekstra intellekt til gruppemedlemmer inden for ", 2, " meter."},
        {"^Gives% (.-)% additional% stamina% to% party% members% within% (.-)% yards%.$", {}, "Giver ", 1, " ekstra udholdenhed til gruppemedlemmer inden for ", 2, " meter."},
        {"^Gives% (.-)% additional% armor% to% nearby% party% members% for% (.-)%.% Players% may% only% have% one% aura% on% them% per% paladin% at% any% one% time%.$", {2}, "Giver ", 1, " ekstra rustning til nærliggende gruppemedlemmer i ", 2, ". Spillere må kun have én glorie på sig pr. Paladin ad gangen."},
        {"^Gives% (.-)% additional% armor% to% party% members% within% (.-)% yards%.% % Players% may% only% have% one% Aura% on% them% per% Paladin% at% any% one% time%.$", {}, "Giver ", 1, " ekstra rustning til gruppemedlemmer inden for ", 2, " meter.  Spillere må kun have én Aura på sig pr. Paladin ad gangen."},
        {"^Gives% (.-)% additional% Fire% resistance% to% all% party% and% raid% members% within% (.-)% yards%.% Players% may% only% have% one% Aura% on% them% per% Paladin% at% any% one% time%.$", {}, "Giver ", 1, " ekstra Ildmodstand til alle gruppe- og togtmedlemmer inden for ", 2, " meter. Spillere må kun have én Aura på sig pr. Paladin ad gangen."},
        {"^Gives% (.-)% additional% Frost% resistance% to% all% party% and% raid% members% within% (.-)% yards%.% Players% may% only% have% one% Aura% on% them% per% Paladin% at% any% one% time%.$", {}, "Giver ", 1, " ekstra Frostmodstand til alle gruppe- og togtmedlemmer inden for ", 2, " meter. Spillere må kun have én Aura på sig pr. Paladin ad gangen."},
        {"^Gives% (.-)% additional% Shadow% resistance% to% all% party% and% raid% members% within% (.-)% yards%.% Players% may% only% have% one% Aura% on% them% per% Paladin% at% any% one% time%.$", {}, "Giver ", 1, " ekstra Skyggemodstand til alle gruppe- og togtmedlemmer inden for ", 2, " meter. Spillere må kun have én Aura på sig pr. Paladin ad gangen."},
        {"^Gives% (.-)% health% to% the% caster%'s% pet% every% second% for% (.-)% as% long% as% the% caster% channels%.% Generates% reduced% threat%.$", {2}, "Giver ", 1, " helbred til udøverens kæledyr hvert sekund i ", 2, ", så længe udøveren kanaliserer. Genererer reduceret trussel."},
