    ["Gives a "] = {
        {"^Gives% a% chance% when% your% harmful% spells% land% to% reduce% the% magical% resistances% of% your% spell% targets% by% (.-)% for% (.-)%.$", {2}, "Giver en chance, når dine skadelige besværgelser rammer, for at reducere besværgelsesmålenes magiske modstand med ", 1, " i ", 2, "."},
        {"^Gives% a% chance% when% your% harmful% spells% land% to% increase% the% damage% of% your% spells% and% effects% by% (.-)% for% (.-)%.$", {2}, "Giver en chance, når dine skadelige besværgelser rammer, for at øge skaden fra dine besværgelser og effekter med ", 1, " i ", 2, "."},
        {"^Gives% a% chance% when% your% harmful% spells% land% to% increase% the% damage% of% your% spells% and% effects% by% (.-)% for% (.-)%.$", {2}, "Giver en chance, når dine skadelige besværgelser rammer, for at øge skaden fra dine besværgelser og effekter med ", 1, " i ", 2, "."},
        {"^Gives% a% chance% to% parry% enemy% melee% attacks%,% reduces% all% threat% generated% by% your% attacks% by% (.-)%%% while% Rockbiter% Weapon% is% not% active%,% and% increases% all% threat% generated% by% (.-)%%% while% Rockbiter% Weapon% is% active%.$", {}, "Giver en chance for at parere fjendtlige nærkampsangreb, reducerer al trussel genereret af dine angreb med ", 1, "%, mens Stenbider-våben ikke er aktivt, og øger al genereret trussel med ", 2, "%, mens Stenbider-våben er aktivt."},
        {"^Gives% a% chance% on% melee% or% ranged% attack% to% apply% an% armor% penetration% effect% on% you% for% (.-)%,% lowering% the% target%'s% physical% armor% by% (.-)% to% your% own% attacks%.% The% armor% penetration% effect% can% be% applied% up% to% 6% times%.$", {1}, "Giver en chance ved nærkamps- eller distanceangreb for at påføre dig selv en rustningsgennemtrængningseffekt i ", 1, ", der sænker målets fysiske rustning med ", 2, " over for dine egne angreb. Rustningsgennemtrængningseffekten kan påføres op til 6 gange."},
        {"^Gives% a% (.-)%%% chance% to% remove% all% movement% impairing% effects% when% you% activate% your% Sprint% ability%.$", {}, "Giver en chance på ", 1, "% for at fjerne alle effekter, der hæmmer bevægelse, når du aktiverer din Spurt-evne."},
        {"^Gives% a% (.-)%%% chance% of% ignoring% spell% interruption% when% damaged% to% all% party% members% within% (.-)% yards%.% % Players% may% only% have% one% Aura% on% them% per% Paladin% at% any% one% time%.$", {}, "Giver en chance på ", 1, "% for at ignorere besværgelsesafbrydelse, når man tager skade, til alle gruppemedlemmer inden for ", 2, " meter.  Spillere må kun have én Aura på sig pr. Paladin ad gangen."},
        {"^Gives% a% (.-)%%% chance% of% ignoring% spell% interruption% when% damaged%.$", {}, "Giver en chance på ", 1, "% for at ignorere besværgelsesafbrydelse, når man tager skade."},
    },
    ["Gives al"] = {
        {"^Gives% all% members% of% the% raid% or% group% that% share% the% same% class% with% the% target% the% Greater% Blessing% of% Light%,% increasing% the% effects% of% Holy% Light% spells% used% on% the% target% by% up% to% (.-)% and% the% effect% Flash% of% Light% spells% used% on% the% target% by% up% to% (.-)%.% % Lasts% (.-)%.% % Players% may% only% have% one% Blessing% on% them% per% Paladin% at% any% one% time%.$", {3}, "Giver alle medlemmer af togtet eller gruppen, der deler samme klasse med målet, den Større Velsignelse af Let, der øger effekten af Hellig Let-besværgelser brugt på målet med op til ", 1, " og effekten af Blitz af Let-besværgelser brugt på målet med op til ", 2, ".  Varer ", 3, ".  Spillere må kun have én Velsignelse på sig pr. Paladin ad gangen."},
