    ["Launches"] = {
        {"^Launches% shadow% infused% orbs% towards% a% random% player% that% travels% out% and% return% to% it%'s% origin%.% Players% hit% are% inflicted% with% (.-)% Shadow% damage$", {}, "Opsender skyggeindspunde kugler mod en tilfældig spiller, der flyver ud og vender tilbage til sit udgangspunkt. Ramte spillere påføres ", 1, " Skyggeskade"},
        {"^Launches% a% mana% infused% orb% toward% a% random% player% that% travels% out% and% returns% to% its% origin%.% Players% hit% are% inflicted% with% (.-)% Arcane% damage%.$", {}, "Opsender en manaindspunden kugle mod en tilfældig spiller, der flyver ud og vender tilbage til sit udgangspunkt. Ramte spillere påføres ", 1, " Arkanskade."},
