    ["Power in"] = {
        {"^Power% infuses% all% party% and% raid% members%,% increasing% their% Shadow% resistance% by% (.-)% for% (.-)%.$", {2}, "Kraften gennemstrømmer alle gruppe- og togtmedlemmer og øger deres Skyggemodstand med ", 1, " i ", 2, "."},
        {"^Power% infuses% all% party% and% raid% members%,% increasing% their% Stamina% by% (.-)% for% (.-)%.$", {2}, "Kraften gennemstrømmer alle gruppe- og togtmedlemmer og øger deres Udholdenhed med ", 1, " i ", 2, "."},
        {"^Power% infuses% all% party% and% raid% members%,% increasing% their% Spirit% by% (.-)% for% (.-)%.$", {2}, "Kraften gennemstrømmer alle gruppe- og togtmedlemmer og øger deres Ånd med ", 1, " i ", 2, "."},
        {"^Power% infuses% the% target%'s% party%,% increasing% their% Stamina% by% (.-)% for% (.-)%.$", {2}, "Kraften gennemstrømmer målets gruppe og øger deres Udholdenhed med ", 1, " i ", 2, "."},
        {"^Power% infuses% the% target%,% increasing% their% Stamina% by% (.-)% for% (.-)%.$", {2}, "Kraften gennemstrømmer målet og øger dets Udholdenhed med ", 1, " i ", 2, "."},
        {"^Power% infuses% the% target% increasing% their% Stamina% by% (.-)% for% (.-)%.$", {2}, "Kraften gennemstrømmer målet og øger dets Udholdenhed med ", 1, " i ", 2, "."},
    },
    ["Prevents"] = {
        {"^Prevents% an% attack% that% would% otherwise% kill% you%.% Triggering% this% effect% also% grants% you% (.-)% of% damage% immunity% and% shatters% the% phylactery%.$", {1}, "Forhindrer et angreb, der ellers ville dræbe dig. Udløsning af denne effekt giver dig også ", 1, " skadesimmunitet og knuser filakteriet."},
    },
    ["Protects"] = {
        {"^Protects% the% target% with% an% earthen% shield%,% reducing% casting% or% channeling% time% lost% when% damaged% by% (.-)%%% % and% causing% attacks% to% heal% the% shielded% target% for% (.-)%.% % This% effect% can% only% occur% once% every% few% seconds%.% % (.-)% charges%.% % Lasts% (.-)%.% % Earth% Shield% can% only% be% placed% on% one% target% at% a% time% and% only% one% Elemental% Shield% can% be% active% on% a% target% at% a% time%.$", {4}, "Beskytter målet med et jordskjold, der reducerer støbe- og kanaliseringstid tabt, når det tager skade med ", 1, "%  og får angreb til at hele det skjoldede mål for ", 2, ".  Denne effekt kan kun indtræffe én gang hvert par sekunder.  ", 3, " ladninger.  Varer ", 4, ".  Jordskjold kan kun placeres på ét mål ad gangen, og kun ét Elementarskjold kan være aktivt på et mål ad gangen."},
        {"^Protects% the% target% with% an% earthen% shield%,% reducing% casting% or% channeling% time% lost% when% damaged% by% (.-)%%% % and% causing% attacks% to% heal% the% shielded% target% for% (.-)%.% % This% effect% can% only% occur% once% every% few% seconds%.% % (.-)% charges%.% Lasts% (.-)%.% % Earth% Shield% can% only% be% placed% on% one% target% at% a% time%.$", {4}, "Beskytter målet med et jordskjold, der reducerer støbe- og kanaliseringstid tabt, når det tager skade med ", 1, "%  og får angreb til at hele det skjoldede mål for ", 2, ".  Denne effekt kan kun indtræffe én gang hvert par sekunder.  ", 3, " ladninger. Varer ", 4, ".  Jordskjold kan kun placeres på ét mål ad gangen."},
        {"^Protects% you% with% a% mana% shield% which% can% absorb% up% to% (.-)% damage%.% Two% points% of% mana% are% drained% per% point% of% damage% taken%.$", {}, "Beskytter dig med et manaskjold, der kan absorbere op til ", 1, " skade. Der drænes to punkter mana pr. punkt modtaget skade."},
        {"^Protects% a% targeted% party% member% from% all% attacks% for% (.-)%.%,% as% well% as% preventing% it% from% attacking% or% using% abilities%.% Players% may% only% have% one% seal% on% them% per% paladin% at% any% one% time%.$", {1}, "Beskytter et valgt gruppemedlem mod alle angreb i ", 1, "., samt forhindrer det i at angribe eller bruge evner. Spillere må kun have ét segl på sig pr. paladin ad gangen."},
        {"^Protects% the% caster% from% all% attacks% and% spells% for% (.-)%.%,% but% also% increases% the% time% between% attacks% by% (.-)%%% during% that% time%.$", {1}, "Beskytter udøveren mod alle angreb og besværgelser i ", 1, "., men øger også tiden mellem angreb med ", 2, "% i den periode."},
        {"^Protects% the% caster% from% all% attacks% and% spells% for% (.-)%.%,% but% during% that% time% the% caster% also% cannot% attack% or% use% spells%.$", {1}, "Beskytter udøveren mod alle angreb og besværgelser i ", 1, "., men i den periode kan udøveren heller ikke angribe eller bruge besværgelser."},
        {"^Protects% the% paladin% from% all% damage% and% spells% for% (.-)%,% but% reduces% all% damage% you% deal% by% (.-)%%%.% % Applies% Forbearance% for% (.-)%.% Cannot% be% cast% while% Forbearance% is% active%.$", {1, 3}, "Beskytter paladinen mod al skade og alle besværgelser i ", 1, ", men reducerer al skade du påfører med ", 2, "%.  Påfører Overbærenhed i ", 3, ".  Kan ikke besværges, mens Overbærenhed er aktiv."},
        {"^Protects% the% caster% from% all% damage% and% spells% for% (.-)%.$", {1}, "Beskytter udøveren mod al skade og alle besværgelser i ", 1, "."},
