    ["Sends bo"] = {
        {"^Sends% bolts% of% holy% power% in% all% directions%,% causing% (.-)% Holy% damage% to% all% targets% within% (.-)% yds% and% Stunning% Demon% and% Undead% targets% for% (.-)%.$", {3}, "Sender lyn af hellig kraft i alle retninger, der forvolder ", 1, " Helligskade til alle mål inden for ", 2, " yd. og bedøver Dæmon- og Udøde-mål i ", 3, "."},
        {"^Sends% bolts% of% holy% power% in% all% directions%,% causing% (.-)% Holy% damage% to% all% Undead% and% Demon% targets% within% (.-)% yds% and% stunning% them% for% (.-)%.$", {3}, "Sender lyn af hellig kraft i alle retninger, der forvolder ", 1, " Helligskade til alle Udøde- og Dæmon-mål inden for ", 2, " yd. og bedøver dem i ", 3, "."},
    },
    ["Sends ou"] = {
        {"^Sends% out% an% ice% blast% that% stuns% and% damages% enemies% in% a% cone% in% front% of% the% caster%,% then% inflicts% additional% Frost% damage% every% (.-)% sec%.% for% (.-)%.$", {2}, "Sender et isudbrud ud, der bedøver og forvolder skade på fjender i en kegle foran udøveren, og derefter påfører ekstra Frostskade hvert ", 1, " sek. i ", 2, "."},
        {"^Sends% out% a% blast% wave% of% magic%,% inflicting% (.-)% Arcane% damage% to% nearby% enemies% and% silencing% them% for% (.-)%.$", {2}, "Sender en udbrudsbølge af magi ud, der påfører ", 1, " Arkanskade til nærliggende fjender og tavsgør dem i ", 2, "."},
        {"^Sends% out% a% blast% wave% of% magic%,% inflicting% (.-)% Arcane% damage% to% nearby% enemies%.$", {}, "Sender en udbrudsbølge af magi ud, der påfører ", 1, " Arkanskade til nærliggende fjender."},
