    ["Serve a "] = {
        {"^Serve% a% delicious% feast% that% lasts% for% (.-)% and% serves% up% to% (.-)% players%.%\n%\n(.-)% (.-)%\n(.-)$", {1}, "Server et lækkert gilde, der varer i ", 1, " og serverer op til ", 2, " spillere.\n\n", 3, " ", 4, "\n", 5},
    },
    ["Sets an "] = {
        {"^Sets% an% enemy% aflame%,% inflicting% (.-)% Fire% damage% over% (.-)%.% and% sending% it% into% a% state% of% panic%.% While% the% target% is% affected%,% the% flames% periodically% scorch% its% nearby% allies% for% (.-)% damage% as% well%.$", {2}, "Sætter en fjende i brand, påfører ", 1, " Ildskade over ", 2, ". og sender den ind i en tilstand af panik. Mens målet er påvirket, svider flammerne periodisk dets nærliggende allierede for ", 3, " skade også."},
        {"^Sets% an% enemy% aflame%,% inflicting% (.-)% Fire% damage% over% (.-)%.% and% sending% it% into% a% state% of% panic%.% While% the% target% is% affected%,% the% flames% periodically% scorch% its% nearby% allies% for% (.-)% damage% as% well%.$", {2}, "Sætter en fjende i brand, påfører ", 1, " Ildskade over ", 2, ". og sender den ind i en tilstand af panik. Mens målet er påvirket, svider flammerne periodisk dets nærliggende allierede for ", 3, " skade også."},
        {"^Sets% an% enemy% aflame%,% inflicting% (.-)% Fire% damage% over% (.-)%.% and% sending% it% into% a% state% of% panic%.% While% the% target% is% affected%,% the% flames% periodically% scorch% its% nearby% allies% for% (.-)% damage% as% well%.$", {2}, "Sætter en fjende i brand, påfører ", 1, " Ildskade over ", 2, ". og sender den ind i en tilstand af panik. Mens målet er påvirket, svider flammerne periodisk dets nærliggende allierede for ", 3, " skade også."},
    },
    ["Shackles"] = {
        {"^Shackles% the% target% undead% enemy% for% up% to% (.-)%.% % The% shackled% unit% is% unable% to% move%,% attack% or% cast% spells%.% % Any% damage% caused% will% release% the% target%.% % Only% one% target% can% be% shackled% at% a% time%.$", {1}, "Lænker det udøde mål i op til ", 1, ".  Den lænkede enhed kan ikke bevæge sig, angribe eller besværge.  Enhver skade forvoldt løser målet.  Kun ét mål kan være lænket ad gangen."},
        {"^Shackles% an% undead% enemy% for% up% to% (.-)%.%,% preventing% it% from% casting% spells%,% attacking%,% or% moving%.% Any% damage% caused% will% release% the% target%.% Only% one% target% can% be% shackled% at% a% time%.$", {1}, "Lænker en udød fjende i op til ", 1, "., og forhindrer den i at besværge, angribe eller bevæge sig. Enhver skade forvoldt løser målet. Kun ét mål kan være lænket ad gangen."},
