    ["Shows th"] = {
        {"^Shows% the% location% of% all% nearby% humanoids% in% Winterax% Hold% for% (.-)%.$", {1}, "Viser placeringen af alle nærliggende humanoider i Vinterøkse-Grebet i ", 1, "."},
