    ["Sunder A"] = {
        {"^Sunder% Armor% also% deals% (.-)%%% weapon% damage%,% increased% by% (.-)%%% per% application% of% Sunder% Armor% already% on% the% target%.$", {}, "Splitningsrustning forvolder også ", 1, "% våbenskade, øget med ", 2, "% pr. påføring af Splitningsrustning allerede på målet."},
    },
    ["Sunder t"] = {
        {"^Sunder% the% target%'s% armor% causing% the% Sunder% Armor% effect%.% % In% addition%,% causes% (.-)%%% of% weapon% damage% plus% (.-)% for% each% application% of% Sunder% Armor% on% the% target%.% % The% Sunder% Armor% effect% can% stack% up% to% (.-)% times%.$", {}, "Splitter målets rustning og forårsager Splitningsrustning-effekten.  Derudover forårsager den ", 1, "% af våbenskade plus ", 2, " for hver påføring af Splitningsrustning på målet.  Splitningsrustning-effekten kan stable op til ", 3, " gange."},
    },
    ["Sunders "] = {
        {"^Sunders% the% target%'s% armor%,% reducing% it% by% (.-)% per% Sunder% Armor% and% causes% a% high% amount% of% threat%.% % Can% be% applied% up% to% 5% times%.% % Lasts% (.-)%.$", {2}, "Splitter målets rustning, reducerer den med ", 1, " pr. Splitningsrustning og forårsager en høj mængde trussel.  Kan påføres op til 5 gange.  Varer ", 2, "."},
    },
    ["Super Ho"] = {
        {"^Super% Hogger% slams% the% ground%,% inflicting% (.-)% Physical% damage% to% enemies% within% (.-)% yds% and% knocking% them% back% a% great% distance%.$", {}, "Super Hugger slår i jorden, påfører fjender inden for ", 2, " yd. ", 1, " Fysisk skade og slynger dem en lang vej tilbage."},
    },
    ["Surge wi"] = {
        {"^Surge% with% fel% energy%,% increasing% your% pet%'s% and% your% own% dodge% chance% by% (.-)%%%,% and% your% chance% to% critically% strike% with% all% attacks% by% (.-)%%%.% Lasts% (.-)%.$", {3}, "Bølger af dæmonisk energi, øger din og dit kæledyrs undvigelseschance med ", 1, "%, og din chance for kritisk stød ved alle angreb med ", 2, "%. Varer ", 3, "."},
    },
    ["Surround"] = {
        {"^Surrounds% the% caster% with% an% aura% that% periodically% reduces% the% Shadow% resistance% of% nearby% enemies% by% (.-)%.% The% aura% lasts% until% cancelled%.$", {}, "Omgiver udøveren med en glorie, der med jævne mellemrum reducerer nærliggende fjenders Skyggemodstand med ", 1, ". Glorien varer, indtil den er annulleret."},
        {"^Surrounds% the% caster% with% an% inferno% that% periodically% inflicts% Fire% damage% to% nearby% enemies% for% (.-)%.% While% the% caster% is% aflame%,% he% cannot% move% or% use% his% abilities%.$", {1}, "Omgiver udøveren med et inferno, der med jævne mellemrum påfører nærliggende fjender Ildskade i ", 1, ". Mens udøveren står i brand, han kan ikke bevæge sig eller bruge hans evner."},
        {"^Surrounds% the% caster% with% an% inferno% that% periodically% inflicts% Fire% damage% to% nearby% enemies% for% (.-)%.% While% the% caster% is% aflame%,% she% cannot% move% or% use% her% abilities%.$", {1}, "Omgiver udøveren med et inferno, der med jævne mellemrum påfører nærliggende fjender Ildskade i ", 1, ". Mens udøveren står i brand, hun kan ikke bevæge sig eller bruge hendes evner."},
        {"^Surrounds% the% target% in% a% shield% of% fire%.% % Every% strike% against% the% target% causes% (.-)% Fire% damage% to% the% attacker%.% % Lasts% (.-)%.% % Your% pet% cannot% cast% Fire% Shield% on% itself%.$", {2}, "Omgiver målet med et Ildskjold.  Hvert stød mod målet forårsager ", 1, " Ildskade til angriberen.  Varer ", 2, ".  Dit kæledyr kan ikke besværge Ildskjold på sig selv."},
        {"^Surrounds% the% target% in% a% shield% of% fire%.% Every% strike% against% the% target% causes% (.-)% Fire% damage% to% the% attacker%.% Lasts% (.-)%.% % Your% pet% cannot% cast% Fire% Shield% on% itself%.$", {2}, "Omgiver målet med et Ildskjold. Hvert stød mod målet forårsager ", 1, " Ildskade til angriberen. Varer ", 2, ".  Dit kæledyr kan ikke besværge Ildskjold på sig selv."},
