    ["The dama"] = {
        {"^The% damage% increases% from% Mercy%'s% and% Crimson% Cleaver%'s% effects% are% increased% by% (.-)%%%.$", {}, "Skadesforøgelserne fra Nådes og Karmosinrød Hakkeknivs effekter øges med ", 1, "%."},
