    ["The deat"] = {
        {"^The% death% of% a% companion% awakens% a% surge% of% energy%,% increasing% damage% dealt% by% (.-)%%% and% attack% speed% by% (.-)%%%.$", {}, "En ledsagers død vækker en energibølge, der øger tilføjet skade med ", 1, "% og angrebshastighed med ", 2, "%."},
    },
    ["The devi"] = {
        {"^The% devices% charges% over% time% using% your% life% force% and% then% directs% a% burst% of% energy% at% your% opponent%.% Deals% (.-)% times% as% much% damage% to% Gnomes%.$", {}, "Apparatet oplader sine ladninger over tid ved hjælp af din livskraft og retter derefter et udbrud af energi mod din modstander. Forvolder ", 1, " gange så meget skade mod Gnomer."},
