    ["The drui"] = {
        {"^The% druid% roars%,% decreasing% nearby% enemies%'% melee% attack% power% by% (.-)%.% % Lasts% (.-)%.$", {2}, "Druiden brøler og reducerer nærliggende fjenders nærkampsangrebskraft med ", 1, ".  Varer ", 2, "."},
    },
    ["The dyna"] = {
        {"^The% dynamite% for% Non%-Engineers% that% nearly% always% gets% to% the% target%!% Inflicts% (.-)% Fire% damage% in% a% 5% yard% radius%.$", {}, "Dynamitten til ikke-ingeniører, der næsten altid rammer målet! Påfører ", 1, " Ildskade i en 5 meter radius."},
    },
    ["The eart"] = {
        {"^The% earth% once% again% swallow% up% Caladbolg% for% (.-)%,% decreasing% movement% speed% by% (.-)%%%.% If% moving%,% your% speed% increases% every% (.-)% seconds%.% Smashing% into% an% enemy% deals% (.-)% fire% damage%,% knocks% back% all% nearby% enemy% players%,% and% ends% this% effect%.$", {1}, "Jorden sluger Kaladbolt igen i ", 1, ", hvilket reducerer bevægelseshastigheden med ", 2, "%. Hvis du bevæger dig, øges din hastighed hvert ", 3, " sekund. Når du smadrer ind i en fjende, forvolder det ", 4, " Ildskade, slår alle nærliggende fjendtlige spillere tilbage og afslutter denne effekt."},
    },
    ["The effe"] = {
        {"^The% effects% of% (.-)%,% (.-)% and% (.-)% are% active%.$", {}, "Effekterne af ", 1, ", ", 2, " og ", 3, " er aktive."},
    },
    ["The end "] = {
        {"^The% end% of% an% epoch% is% nigh%!%\nMovement% speed% increased% by% (.-)%%%.%\nDamage% taken% reduced% by% (.-)%%%.%\nHealth% increased% by% (.-)%%%.$", {}, "Slutningen af en epoke er nær!\nBevægelseshastighed øget med ", 1, "%.\nModtagne skade reduceret med ", 2, "%.\nHelbred øget med ", 3, "%."},
    },
    ["The enem"] = {
        {"^The% enemy% target% is% swarmed% by% insects%,% decreasing% their% chance% to% hit% with% attacks% by% (.-)%%% and% causing% (.-)% Nature% damage% over% (.-)%.$", {3}, "Fjendens mål overmandes af en svarm af insekter, hvilket reducerer deres træfchance for angreb med ", 1, "% og forvolder ", 2, " Naturskade over ", 3, "."},
    },
    ["The ener"] = {
        {"^The% energy% cost% of% your% Rake% and% Rip% spells% is% reduced% by% (.-)%.$", {}, "Energiomkostningen for dine Rive- og Riv-besværgelser er reduceret med ", 1, "."},
    },
    ["The forc"] = {
        {"^The% forces% of% the% Scourge% grow% stronger%.% Chance% to% dodge% reduced% by% (.-)%%% and% chance% to% be% hit% increased% by% (.-)%%%.%\n%\nThe% benefits% from% your% Seal% of% the% Dawn% cannot% exceed% Rank% (.-)%.$", {}, "Svøbens kræfter bliver stærkere. Chance for at undvige reduceres med ", 1, "%, og chance for at blive ramt øges med ", 2, "%.\n\nFordelene fra dit Segl af Daggry kan ikke overstige Rang ", 3, "."},
        {"^The% forces% of% the% Scourge% grow% stronger%.% Chance% to% dodge% reduced% by% (.-)%%% and% chance% to% be% hit% increased% by% (.-)%%%.%\n%\nThe% benefits% from% your% Seal% of% the% Dawn% cannot% exceed% Rank% (.-)%.$", {}, "Svøbens kræfter bliver stærkere. Chance for at undvige reduceres med ", 1, "%, og chance for at blive ramt øges med ", 2, "%.\n\nFordelene fra dit Segl af Daggry kan ikke overstige Rang ", 3, "."},
        {"^The% forces% of% the% Scourge% grow% stronger%.% Chance% to% dodge% reduced% by% (.-)%%% and% chance% to% be% hit% increased% by% (.-)%%%.% %\n%\nThe% benefits% from% your% Seal% of% the% Dawn% cannot% exceed% Rank% (.-)%.$", {}, "Svøbens kræfter bliver stærkere. Chance for at undvige reduceres med ", 1, "%, og chance for at blive ramt øges med ", 2, "%. \n\nFordelene fra dit Segl af Daggry kan ikke overstige Rang ", 3, "."},
    },
    ["The hunt"] = {
        {"^The% hunter% takes% on% the% aspect% of% the% viper%,% causing% your% ranged% and% melee% auto% attacks% to% regenerate% mana% but% reducing% your% total% damage% done% by% (.-)%%%.% % In% addition%,% you% gain% (.-)%%% of% maximum% mana% every% (.-)% sec%.% % Mana% gained% is% based% on% the% speed% of% your% weapon%.% Only% one% Aspect% can% be% active% at% a% time%.$", {}, "Jægeren tager Hugormens skikkelse på sig, hvilket får dine distance- og nærkampsautoangreb til at generere mana, men reducerer din samlede forvoldte skade med ", 1, "%.  Desuden får du ", 2, "% af maksimal mana hvert ", 3, " sek.  Opnået mana afhænger af hastigheden på dit våben. Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% takes% on% the% aspect% of% the% viper%,% causing% ranged% and% melee% attacks% to% regenerate% mana% but% reducing% your% total% damage% done% by% (.-)%%%.% % In% addition%,% you% gain% (.-)%%% of% maximum% mana% every% (.-)% sec%.% % Mana% gained% is% based% on% the% speed% of% your% ranged% weapon%.% Requires% a% ranged% weapon%.% Only% one% Aspect% can% be% active% at% a% time%.$", {}, "Jægeren tager Hugormens skikkelse på sig, hvilket får distance- og nærkampsangreb til at generere mana, men reducerer din samlede forvoldte skade med ", 1, "%.  Desuden får du ", 2, "% af maksimal mana hvert ", 3, " sek.  Opnået mana afhænger af hastigheden på dit distancevåben. Kræver et distancevåben. Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% takes% on% the% aspects% of% a% beast%,% becoming% untrackable% and% increasing% Melee% Attack% Power% by% (.-)%.% Only% one% Aspect% can% be% active% at% a% time%.$", {}, "Jægeren tager udyrets skikkelser på sig, bliver uopsporlig og øger Nærkamps Angrebskraft med ", 1, ". Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% takes% on% the% aspects% of% a% hawk%,% increasing% Ranged% Attack% Power% by% (.-)%.% % Only% one% Aspect% can% be% active% at% a% time%.$", {}, "Jægeren tager høgens skikkelser på sig og øger Distance Angrebskraft med ", 1, ".  Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% takes% on% the% aspects% of% a% monkey%,% increasing% chance% to% dodge% by% (.-)%%%.% % Only% one% Aspect% can% be% active% at% a% time%.$", {}, "Jægeren tager abens skikkelser på sig og øger chance for at undvige med ", 1, "%.  Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% takes% on% the% aspects% of% a% cheetah%,% increasing% movement% speed% by% (.-)%%%.% % If% the% hunter% takes% damage%,% he% will% be% dazed% for% (.-)%.% % Only% one% Aspect% can% be% active% at% a% time%.$", {2}, "Jægeren tager gepardens skikkelser på sig og øger bevægelseshastigheden med ", 1, "%.  Hvis jægeren tager skade, bliver he omtåget i ", 2, ".  Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% takes% on% the% aspects% of% a% cheetah%,% increasing% movement% speed% by% (.-)%%%.% % If% the% hunter% takes% damage%,% she% will% be% dazed% for% (.-)%.% % Only% one% Aspect% can% be% active% at% a% time%.$", {2}, "Jægeren tager gepardens skikkelser på sig og øger bevægelseshastigheden med ", 1, "%.  Hvis jægeren tager skade, bliver she omtåget i ", 2, ".  Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% invokes% the% heart% of% a% lion%,% increasing% total% stats% by% (.-)%%% and% Attack% Power% by% (.-)% for% all% nearby% allies%,% and% increasing% total% stats% for% the% Hunter% by% an% additional% (.-)%%%.$", {}, "Jægeren påkalder et løvehjerte, der øger samlede egenskaber med ", 1, "% og Angrebskraft med ", 2, " for alle nærliggende allierede, og øger samlede egenskaber for Jægeren med yderligere ", 3, "%."},
        {"^The% hunter% invokes% the% heart% of% a% lion%,% increasing% total% stats% by% (.-)%%% for% all% nearby% allies%,% and% increasing% total% stats% for% the% Hunter% by% an% additional% (.-)%%%.$", {}, "Jægeren påkalder et løvehjerte, der øger samlede egenskaber med ", 1, "% for alle nærliggende allierede, og øger samlede egenskaber for Jægeren med yderligere ", 2, "%."},
        {"^The% hunter% and% all% party% and% raid% members% within% (.-)% yards% take% on% the% aspect% of% the% wild%,% increasing% Nature% resistance% by% (.-)%.% % Only% one% Aspect% can% be% active% at% a% time%.$", {}, "Jægeren og alle grupper- og togt-medlemmer inden for ", 1, " meter tager den vilde skikkelse på sig og øger Naturmodstand med ", 2, ".  Kun ét Aspekt kan være aktivt ad gangen."},
        {"^The% hunter% and% group% members% within% (.-)% yards% take% on% the% aspects% of% a% pack% of% cheetahs%,% increasing% movement% speed% by% (.-)%%%.% % If% a% pack% member% takes% damage%,% they% will% be% dazed% for% (.-)%.% % Only% one% Aspect% can% be% active% at% a% time%.$", {3}, "Jægeren og gruppemedlemmer inden for ", 1, " meter tager en gepardfloks skikkelser på sig og øger bevægelseshastigheden med ", 2, "%.  Hvis et flokmedlem tager skade, bliver de omtåget i ", 3, ".  Kun ét Aspekt kan være aktivt ad gangen."},
