    ["The powe"] = {
        {"^The% power% of% the% Emerald% Dream% seeps% out% of% Nythus%,% increasing% mana% regeneration% for% all% players% by% (.-)%%% but% increasing% all% the% damage% they% receive% by% (.-)%%%.%\n%\nHaste% is% also% increased% by% (.-)%%%.$", {}, "Kraften fra Den Smaragdgrønne Drøm sive ud af Nytus og øger managenoprettelsen for alle spillere med ", 1, "%, men øger al den skade, de modtager, med ", 2, "%.\n\nHastighed øges også med ", 3, "%."},
        {"^The% power% of% the% Emerald% Dream% seeps% out% of% Nythus%,% reducing% his% mana% regeneration% by% 100%%% for% (.-)%.$", {1}, "Kraften fra Den Smaragdgrønne Drøm sive ud af Nytus og reducerer hans managenoprettelse med 100% i ", 1, "."},
        {"^The% power% of% Elune% blesses% the% waters%,% increasing% swim% speed% by% (.-)%%% per% application%.$", {}, "Elunies kraft velsigner vandet og øger svømmehastigheden med ", 1, "% pr. påføring."},
    },
    ["The prie"] = {
