    ["The targ"] = {
        {"^The% target%'s% skin% becomes% as% tough% as% bark%.% Physical% damage% taken% is% reduced% by% (.-)%%%.% % While% protected%,% damaging% attacks% will% not% cause% spellcasting% delays%.% Lasts% (.-)%.$", {2}, "Målets hud bliver hård som bjæffe. Den modtagne fysiske skade reduceres med ", 1, "%.  Mens den er beskyttet, vil skadende angreb ikke forårsage besværgelsesforsinkelser. Varer ", 2, "."},
        {"^The% targeted% undead% enemy% will% be% compelled% to% flee% for% up% to% (.-)%.% % Damage% caused% may% interrupt% the% effect%.% % Only% one% target% can% be% turned% at% a% time%.$", {1}, "Den udvalgte udøde fjende vil blive tvunget til at flygte i op til ", 1, ".  Forvoldt skade kan afbryde effekten.  Kun ét mål kan vendes ad gangen."},
        {"^The% target% of% your% Spirit% of% the% Alpha% ability% takes% (.-)%%% reduced% damage% from% Undead% enemies%.$", {}, "Målet for din evne Alfaens Ånd modtager ", 1, "% reduceret skade fra Udøde fjender."},
        {"^The% target% becomes% a% Living% Bomb%,% taking% (.-)% Fire% damage% over% (.-)%.% % After% (.-)% or% when% the% spell% is% dispelled%,% the% target% explodes% dealing% (.-)% Fire% damage% to% all% enemies% within% (.-)% yards%.$", {2, 3}, "Målet bliver en Levende Bombe og tager ", 1, " Ildskade i løbet af ", 2, ".  Efter ", 2, ", eller når besværgelsen fjernes, eksploderer målet og forvolder ", 4, " Ildskade til alle fjender inden for ", 5, " meter."},
        {"^The% target% becomes% a% Living% Bomb%,% taking% (.-)% Fire% damage% over% (.-)%.% % After% (.-)% or% when% the% spell% is% dispelled%,% the% target% explodes% dealing% (.-)% Fire% damage% to% all% enemies% within% (.-)% yards%.%\n%\nLiving% Bomb% benefits% from% all% talents% and% effects% that% trigger% from% or% modify% Scorch%.$", {2, 3}, "Målet bliver en Levende Bombe og tager ", 1, " Ildskade i løbet af ", 2, ".  Efter ", 2, ", eller når besværgelsen fjernes, eksploderer målet og forvolder ", 4, " Ildskade til alle fjender inden for ", 5, " meter.\n\nLevende Bombe drager fordel af alle talenter og effekter, der udløses af eller ændrer Forbrænding."},
    },
    ["The warr"] = {
        {"^The% warrior% enters% a% berserker% rage%,% becoming% immune% to% Fear% and% Incapacitate% effects% and% generating% extra% rage% when% taking% damage%.% % Lasts% (.-)%.$", {1}, "Krigeren går i berserkerraseri, bliver immun over for Frygt- og Lammelseseffekter og genererer ekstra raseri, når der tages skade.  Varer ", 1, "."},
        {"^The% warrior% shouts%,% increasing% the% melee% attack% power% of% all% party% or% raid% members% within% (.-)% yards% by% (.-)%.% % Lasts% (.-)%.$", {3}, "Krigeren råber og øger nærkampsangrebskraften for alle gruppe- eller togt-medlemmer inden for ", 1, " meter med ", 2, ".  Varer ", 3, "."},
        {"^The% warrior% shouts%,% increasing% the% attack% power% of% all% party% members% within% (.-)% yards% by% (.-)%.% % Lasts% (.-)%.$", {3}, "Krigeren råber og øger angrebskraften for alle gruppemedlemmer inden for ", 1, " meter med ", 2, ".  Varer ", 3, "."},
        {"^The% warrior% shouts%,% causing% the% targeted% enemy% to% cower% in% fear%.% % Up% to% (.-)% enemies% within% (.-)% yds% will% flee% in% fear%.% % Lasts% (.-)%.$", {3}, "Krigeren råber, og den valgte fjende krymper sig i frygt.  Op til ", 1, " fjender inden for ", 2, " yd. flygter i frygt.  Varer ", 3, "."},
        {"^The% warrior% shouts%,% increasing% the% Stamina% of% all% party% members% within% (.-)% yards% by% (.-)%.% % Lasts% (.-)%.$", {3}, "Krigeren råber og øger Udholdenheden for alle gruppemedlemmer inden for ", 1, " meter med ", 2, ".  Varer ", 3, "."},
        {"^The% warrior% will% gain% (.-)%%% increased% critical% strike% chance% and% will% be% immune% to% Fear% effects% for% the% next% (.-)%,% but% all% damage% taken% is% increased% by% (.-)%%%.$", {2}, "Krigeren vil få ", 1, "% øget kritisk angrebschance og vil være immun over for Frygt-effekter i de næste ", 2, ", men al modtaget skade øges med ", 3, "%."},
