    ["Unfolds "] = {
        {"^Unfolds% into% a% G00% DV%-1B3% Generator% that% can% repair% damaged% items% and% purchase% unwanted% goods%.% % After% (.-)% its% internal% motor% fails% and% it% must% recover%.$", {1}, "Folder sig ud til en G00 DV-1B3-generator, der kan reparere beskadigede genstande og købe uønskede varer.  Efter ", 1, " svigter dens interne motor, og den må hente sig."},
    },
    ["Unleash "] = {
        {"^Unleash% all% of% your% remaining% mana% in% a% surge% of% energy% focused% at% the% target% dealing% (.-)% to% (.-)% Arcane% damage%,% increased% by% up% to% (.-)%%% based% on% your% mana% remaining%.% Afterward%,% your% normal% mana% regeneration% is% activated% and% increased% by% (.-)%%% for% (.-)%.$", {5}, "Udløs al din resterende mana i en energibølge rettet mod målet, der forvolder ", 1, " til ", 2, " Arkanskade, øget med op til ", 3, "% baseret på din resterende mana. Derefter aktiveres din normale managenoprettelse og øges med ", 4, "% i ", 5, "."},
        {"^Unleash% stored% chronomantic% energy% to% instantly% heal% a% friendly% target% for% (.-)to% (.-)%.$", {}, "Udløs lagret kronomantisk energi for øjeblikkeligt at helbrede et venligt mål for ", 1, "til ", 2, "."},
        {"^Unleash% a% flourish% of% steel% and% blood%,% wounding% all% enemy% targets% within% (.-)% yards%,% dealing% (.-)% Shadowstrike% damage%,% and% causing% them% to% bleed% for% an% additional% (.-)% damage% every% (.-)% sec% for% (.-)%.$", {5}, "Udløs et udbrud af stål og blod, der sårer alle fjendtlige mål inden for ", 1, " meter, forvolder ", 2, " Skyggestødskade og får dem til at blø for yderligere ", 3, " skade hvert ", 4, " sek. i ", 5, "."},
        {"^Unleash% a% reality%-distorting% burst% of% raw% magic% at% your% enemy%,% dealing% (.-)% to% (.-)% Chimeric% damage%.%\n%\nIncreasing% your% Balefire% Bolt% and% Pyroblast% damage% by% (.-)%%%,% decreasing% your% Spirit% by% (.-)%%%,% and% stacking% up% to% (.-)% times% for% (.-)%.% If% your% Spirit% reaches% 0%,% you% die%.%\n%\nThis% spell% will% be% checked% against% the% lower% of% the% target%'s% Arcane%,% Fire%,% and% Frost% resists%.$", {6}, "Udløs et virkelighedsforvrængende udbrud af rå magi mod din fjende, der forvolder ", 1, " til ", 2, " Chimærskade.\n\nØger skaden fra din Dødsild Bolt og Ildstød med ", 3, "%, formindsker din Ånd med ", 4, "% og stabler op til ", 5, " gange i ", 6, ". Hvis din Ånd når 0, dør du.\n\nDenne besværgelse bliver tjekket mod den laveste af målets Arkan-, Ild- og Frostmodstand."},
        {"^Unleash% a% shadow% bolt% volley% at% all% nearby% targets%,% inflicting% (.-)% damage% to% each% enemy% struck%.$", {}, "Udløs en salve af skyggelyn mod alle nærliggende mål, der påfører ", 1, " skade til hver ramt fjende."},
        {"^Unleash% a% delayed% explosion% of% blood% and% nature%,% causing% (.-)% Plague% damage% to% all% targets% within% (.-)% yards%.$", {}, "Udløs en forsinket eksplosion af blod og natur, der forvolder ", 1, " Pestskade til alle mål inden for ", 2, " meter."},
        {"^Unleash% a% delayed% explosion% of% blood% and% light%,% causing% (.-)% Twilight% damage% to% all% targets% within% (.-)% yards%.$", {}, "Udløs en forsinket eksplosion af blod og lys, der forvolder ", 1, " Tusmørkeskade til alle mål inden for ", 2, " meter."},
        {"^Unleash% a% delayed% explosion% of% blood% and% fire%,% causing% (.-)% Shadowflame% damage% to% all% targets% within% (.-)% yards%.$", {}, "Udløs en forsinket eksplosion af blod og ild, der forvolder ", 1, " Skyggeflammeskade til alle mål inden for ", 2, " meter."},
        {"^Unleash% a% violent% tempest% of% steel% and% blood%,% causing% (.-)% Shadowstrike% damage% to% all% enemies% within% (.-)% yards%.$", {}, "Udløs en voldsom storm af stål og blod, der forvolder ", 1, " Skyggestødskade til alle fjender inden for ", 2, " meter."},
        {"^Unleash% a% belch% of% dragonfire%,% dealing% (.-)% Fire% damage% instantly% in% a% narrow% cone% in% front% of% you%.% Affected% targets% will% suffer% (.-)% additional% damage% every% (.-)% sec% for% (.-)%.$", {4}, "Udløs et bøvs af drageild, der forvolder ", 1, " Ildskade øjeblikkeligt i en smal kegle foran dig. Ramte mål lider ", 2, " ekstra skade hvert ", 3, " sek. i ", 4, "."},
        {"^Unleash% a% poisonous% sting% that% deals% (.-)% nature% damage%,% and% hits% (.-)% additional% nearby% targets%.$", {}, "Udløs et giftigt stik, der forvolder ", 1, " naturskade og rammer ", 2, " ekstra nærliggende mål."},
        {"^Unleash% a% cloud% of% lethargy% in% a% (.-)% yd% % radius%.% Enemies% that% attack% within% the% cloud% have% a% (.-)%%% chance% to% succumb% to% sleep% for% (.-)%.% Lasts% for% (.-)%.$", {3, 4}, "Udløs en sky af sløvhed i en radius på ", 1, " yd. Fjender, der angriber inden for skyen, har en ", 2, "% chance for at segne hen i søvn i ", 3, ". Varer i ", 4, "."},
        {"^Unleash% a% mighty% swing%,% dealing% (.-)% Holy% damage%.% Deals% (.-)% times% as% much% damage% to% Undead% and% Swine%.$", {}, "Udløs et kraftigt hug, der forvolder ", 1, " Helligskade. Forvolder ", 2, " gange så meget skade mod Udøde og Svin."},
    },
    ["Unleashe"] = {
        {"^Unleashes% a% barrage% of% bolts% at% a% target%'s% location%,% inflicting% Physical% damage% to% players% in% a% cone% in% front% of% the% caster% every% sec% for% (.-)%.$", {1}, "Udløser en salve af lyn mod et måls placering, der påfører spillere i en kegle foran udøveren fysisk skade hvert sek. i ", 1, "."},
        {"^Unleashes% a% wave% of% flame%,% inflicting% Fire% damage% to% nearby% enemies% and% reducing% their% movement% speed% for% (.-)%.$", {1}, "Udløser en flammebølge, der påfører nærliggende fjender Ildskade og reducerer deres bevægelseshastighed i ", 1, "."},
        {"^Unleashes% fel% magic% on% death%,% dealing% (.-)% Shadow% damage% to% all% enemies% within% (.-)% yds%.$", {}, "Udløser dæmonisk magi ved død, der forvolder ", 1, " Skyggeskade til alle fjender inden for ", 2, " meter."},
