        {"^Wounds% the% target% for% (.-)% damage% and% lowers% their% armor% by% (.-)%.$", {}, "Sårer målet for ", 1, " skade og sænker dets rustning med ", 2, "."},
        {"^Wounds% the% target% for% (.-)% damage%.$", {}, "Sårer målet for ", 1, " skade."},
        {"^Wounds% the% target% for% (.-)% damage%.% Naga% are% Stunned% for% (.-)%.$", {2}, "Sårer målet for ", 1, " skade. Slangefolk er bedøvet i ", 2, "."},
        {"^Wounds% the% target% for% (.-)% damage%.% Naga% are% Stunned% for% (.-)% sec%.$", {}, "Sårer målet for ", 1, " skade. Slangefolk er bedøvet i ", 1, " sek."},
