    ["You atta"] = {
        {"^You% attack% all% nearby% enemies% for% (.-)% causing% weapon% damage% plus% an% additional% (.-)% every% (.-)% sec%.$", {1}, "Du angriber alle nærliggende fjender for ", 1, " våbenskade plus en ekstra ", 2, " hvert ", 3, " sek."},
        {"^You% attack% all% nearby% enemies% for% (.-)% causing% weapon% damage% plus% an% additional% (.-)% every% (.-)% sec%.$", {1}, "Du angriber alle nærliggende fjender for ", 1, " våbenskade plus en ekstra ", 2, " hvert ", 3, " sek."},
    },
    ["You atte"] = {
        {"^You% attempt% to% finish% off% a% wounded% target%,% firing% a% ranged% attack% dealing% (.-)%%% weapon% damage% plus% (.-)%.% Kill% Shot% has% no% minimum% range%.% Kill% Shot%'s% cooldown% is% reset% if% used% on% an% enemy% that% has% 20%%% or% less% health%.$", {}, "Du forsøger at gøre en såret modstander færdig med et distanceskud, der forvolder ", 1, "% våbenskade plus ", 2, ". Dræb-skud har ingen minimumsrækkevidde. Dræb-skuds genopladning nulstilles, hvis det bruges på en fjende med 20% eller mindre helbred."},
    },
    ["You bash"] = {
        {"^You% bash% the% target%'s% skull%,% interrupting% spellcasting% and% preventing% any% spell% in% that% school% from% being% cast% for% (.-)%.$", {1}, "Du slår mod målets kranium, afbryder besværgelsen og forhindrer enhver besværgelse i den skole i at blive besværget i ", 1, "."},
    },
    ["You beco"] = {
        {"^You% become% encased% in% a% block% of% ice%,% protecting% you% from% all% physical% attacks% and% spells% for% (.-)%,% but% during% that% time% you% cannot% attack%,% move% or% cast% spells%.$", {1}, "Du bliver indesluttet i en isblok, der beskytter dig mod alle fysiske angreb og besværgelser i ", 1, ", men i den tid kan du ikke angribe, bevæge dig eller besværge."},
        {"^You% become% encased% in% a% block% of% ice%,% protecting% you% from% all% physical% attacks% and% spells% for% (.-)%,% but% during% that% time% you% cannot% attack%,% move%,% or% cast% spells%.$", {1}, "Du bliver indesluttet i en isblok, der beskytter dig mod alle fysiske angreb og besværgelser i ", 1, ", men i den tid kan du ikke angribe, bevæge dig eller besværge."},
    },
    ["You can "] = {
        {"^You% can% now% take% actions% during% Divine% Protection% and% its% duration% is% increased% by% (.-)%%%,% but% it% only% reduces% damage% you% take% by% (.-)%%% instead% of% making% you% immune%.% In% addition%,% activating% Holy% Shield% also% grants% you% (.-)% Attack% Power% for% each% point% of% your% defense% skill% beyond% (.-)%,% lasting% (.-)%.$", {5}, "Du kan nu handle under Guddommelig Beskyttelse, og dens varighed øges med ", 1, "%, men den reducerer kun den skade, du tager, med ", 2, "% i stedet for at gøre dig immun. Desuden giver aktivering af Hellig Skjold dig også ", 3, " Angrebskraft for hvert punkt af din forsvarsfærdighed ud over ", 4, ", varende ", 5, "."},
        {"^You% can% breathe% underwater% and% your% swim% speed% is% increased% by% (.-)%%%.% Some% combat% actions% may% break% this% effect%.$", {}, "Du kan trække vejret under vand, og din svømmehastighed øges med ", 1, "%. Nogle kamphandlinger kan bryde denne effekt."},
    },
    ["You cann"] = {
        {"^You% cannot% gain% more% rested% experience% from% a% Camp% Tent% for% (.-)%.$", {1}, "Du kan ikke opnå mere udhvilet erfaring fra et Lejrtelt i ", 1, "."},
    },
    ["You char"] = {
        {"^You% charge% your% off%-hand% weapon% with% lava%,% instantly% dealing% (.-)%%% off%-hand% Weapon% damage%.% Damage% is% increased% by% (.-)%%% if% your% off%-hand% weapon% is% enchanted% with% Flametongue%.$", {}, "Du lader dit bivåben med lava, og forvolder øjeblikkeligt ", 1, "% bivåbenskade. Skaden øges med ", 2, "%, hvis dit bivåben er fortryllet med Flammetunge."},
    },
    ["You deal"] = {
        {"^You% deal% (.-)%%% weapon% damage%,% refreshing% the% current% Sting% on% your% target% and% triggering% an% effect%:%\n%\nSerpent% Sting% %-% Instantly% deals% (.-)%%% of% the% damage% done% by% your% Serpent% Sting%.%\n%\nViper% Sting% %-% Instantly% restores% mana% to% you% equal% to% (.-)%%% of% the% total% amount% drained% by% your% Viper% Sting%.%\n%\nScorpid% Sting% %-% Attempts% to% Disarm% the% target% for% (.-)%.% This% effect% cannot% occur% more% than% once% per% 1% minute%.$", {4}, "Du forvolder ", 1, "% våbenskade, genopfrisker den nuværende Brod på dit mål og udløser en effekt:\n\nSlangebrod - Forvolder øjeblikkeligt ", 2, "% af den skade, din Slangebrod forvoldte.\n\nHugorm-brod - Gendanner øjeblikkeligt mana til dig svarende til ", 3, "% af den samlede mængde, din Hugorm-brod drænede.\n\nSkorpidbrod - Forsøger at afvæbne målet i ", 4, ". Denne effekt kan ikke forekomme mere end én gang pr. 1 minut."},
        {"^You% deal% (.-)%%% increased% damage% while% any% nearby% enemy% is% afflicted% with% both% your% Rend% and% your% Deep% Wounds%.$", {}, "Du forvolder ", 1, "% øget skade, mens en nærliggende fjende er ramt af både din Flænse og dine Dybe Sår."},
        {"^You% deal% (.-)%%% more% damage% while% you% have% more% than% (.-)%%% mana%.% While% below% (.-)%%% mana% (.-)%%% of% your% mana% regeneration% continues% while% casting%.$", {}, "Du forvolder ", 1, "% mere skade, mens du har mere end ", 2, "% mana. Når du er under ", 3, "% mana, fortsætter ", 4, "% af din managenoprettelse under støbning."},
        {"^You% deal% (.-)%%% increased% damage% with% all% attacks% while% you% do% not% have% an% active% pet%.$", {}, "Du forvolder ", 1, "% øget skade med alle angreb, mens du ikke har et aktivt kæledyr."},
    },
    ["You disp"] = {
        {"^You% disperse% into% pure% Shadow% energy%,% reducing% all% damage% taken% by% (.-)%%%.% % You% are% unable% to% attack% or% cast% spells%,% but% you% regenerate% (.-)%%% mana% every% (.-)% sec% for% (.-)%.% Dispersion% can% be% cast% while% stunned%,% feared% or% silenced% and% clears% all% snare% and% movement% impairing% effects% when% cast%,% and% makes% you% immune% to% them% while% dispersed%.$", {4}, "Du spredes ud i ren Skyggeenergi, hvilket reducerer al modtagen skade med ", 1, "%.  Du kan ikke angribe eller besværge besværgelser, men du genopretter ", 2, "% mana hvert ", 3, " sek. i ", 4, ". Spredning kan besværges, mens du er bedøvet, frygtet eller tavsgjort, og den fjerner alle fælde- og bevægelseshæmmende effekter, når den besværges, og gør dig immun over for dem, mens du er spredt."},
    },
    ["You feel"] = {
        {"^You% feel% inspired%!% Experience% gains% increased% by% (.-)%%%.$", {}, "Du føler dig inspireret! Erfaringsgevinster er øget med ", 1, "%."},
        {"^You% feel% refreshed%!% % %+(.-)% Stamina%!$", {}, "Du føler dig genopfrisket!  +", 1, " Udholdenhed!"},
    },
    ["You gain"] = {
        {"^You% gain% a% charge% of% Gathering% Storm% each% time% you% cause% a% damaging% spell% critical% strike%.% When% you% reach% (.-)% charges% of% Gathering% Storm%,% they% will% release%,% firing% an% Unleashed% Storm% for% (.-)% damage%.% Gathering% Storm% cannot% be% gained% more% often% than% once% every% 2% sec%.$", {}, "Du får en ladning af Samlende Storm hver gang du forårsager et skadevoldende besværgelses kritisk angreb. Når du når ", 1, " ladninger af Samlende Storm, frigøres de og affyrer en Løsluppet Storm, der forvolder ", 2, " skade. Samlende Storm kan ikke opnås oftere end én gang hvert 2 sek."},
        {"^You% gain% talent% points% every% level% starting% at% level% (.-)% instead% of% starting% at% level% 10%,% but% you% still% may% not% have% more% than% 51% total% talent% points%.$", {}, "Du får talentpoint for hvert niveau, startende ved niveau ", 1, " i stedet for ved niveau 10, men du må stadig ikke have mere end 51 talentpoint samlet."},
        {"^You% gain% an% additional% (.-)% Rage% from% activating% Enrage% and% an% additional% (.-)% Energy% from% activating% Shifting% Power%.$", {}, "Du får ekstra ", 1, " Vrede ved at aktivere Rasende og ekstra ", 2, " Energi ved at aktivere Skiftende Kraft."},
        {"^You% gain% (.-)%%% increased% damage% and% critical% damage% done% to% Undead% for% (.-)% each% time% you% hit% an% Undead% enemy% with% a% melee% attack%,% stacking% up% to% (.-)% times%.% Stacks% are% lost% upon% performing% a% ranged% attack%.$", {2}, "Du får ", 1, "% øget skade og kritisk skade gjort mod Udøde i ", 2, ", hver gang du rammer en udød fjende med et nærkampsangreb, og stakker op til ", 3, " gange. Stakke går tabt, når du udfører et distanceangreb."},
        {"^You% gain% (.-)%%% increased% damage% and% critical% damage% done% to% Undead% for% (.-)% per% Combo% Point% you% spend%,% stacking% up% to% (.-)% times%.$", {2}, "Du får ", 1, "% øget skade og kritisk skade gjort mod Udøde i ", 2, " per Kombinationspoint, du bruger, og stakker op til ", 3, " gange."},
        {"^You% gain% (.-)%%% increased% damage% and% critical% damage% done% to% Undead% for% (.-)% for% each% time% your% Overload% triggers% from% an% offensive% spell% cast%,% stacking% up% to% (.-)% times%.$", {2}, "Du får ", 1, "% øget skade og kritisk skade gjort mod Udøde i ", 2, ", for hver gang din Overbelastning udløses af en offensiv besværgelse, du besværger, og stakker op til ", 3, " gange."},
        {"^You% gain% (.-)%%% increased% damage% and% critical% damage% done% to% Undead% for% (.-)% for% each% charge% of% Maelstrom% Weapon% you% earn%,% stacking% up% to% (.-)% times%.$", {2}, "Du får ", 1, "% øget skade og kritisk skade gjort mod Udøde i ", 2, ", for hver ladning Malstrømsvåben, du optjener, og stakker op til ", 3, " gange."},
        {"^You% gain% (.-)% Energy% each% time% Rake% or% Rip% deals% periodic% damage%.$", {}, "Du får ", 1, " Energi, hver gang Rive eller Riv forvolder periodisk skade."},
        {"^You% gain% (.-)%%% increased% attack% speed% for% (.-)% every% time% you% deal% a% critical% strike%.$", {2}, "Du får ", 1, "% øget angrebshastighed i ", 2, ", hver gang du forvolder et kritisk angreb."},
        {"^You% gain% (.-)%%% increased% damage% and% critical% damage% done% to% Undead% for% (.-)% each% time% you% hit% an% Undead% enemy% with% a% ranged% attack%,% stacking% up% to% (.-)% times%.$", {2}, "Du får ", 1, "% øget skade og kritisk skade gjort mod Udøde i ", 2, ", hver gang du rammer en udød fjende med et distanceangreb, og stakker op til ", 3, " gange."},
        {"^You% gain% (.-)%%% of% your% maximum% mana% every% (.-)% sec% for% (.-)% after% Blocking% a% melee% attack%.% This% effect% is% cancelled% by% casting% Flash% of% Light%,% Holy% Light%,% or% Holy% Shock%.$", {3}, "Du får ", 1, "% af din maksimale mana hvert ", 2, " sek. i ", 3, " efter en Blokering af et nærkampsangreb. Denne effekt annulleres, når du besværger Blitz af Let, Hellig Let eller Hellig Chok."},
        {"^You% gain% (.-)% Energy% every% time% you% deal% a% melee% or% ranged% critical% strike%.$", {}, "Du får ", 1, " Energi, hver gang du forvolder et kritisk angreb i nærkamp eller på distance."},
        {"^You% gain% (.-)%%% movement% speed% for% (.-)% after% using% Raptor% Strike%.%\n%\nYour% pet%'s% damaging% abilities% send% the% target% into% a% Rabid% Frenzy%,% increasing% their% melee% attack% power% by% (.-)% but% reducing% armor% by% (.-)% for% (.-)%.% % Rabid% enemies% will% not% flee% and% will% ignore% Fear% and% Horror% effects%.$", {2, 5}, "Du får ", 1, "% bevægelseshastighed i ", 2, ", efter du har brugt Rovfuglslag.\n\nDit kæledyrs skadelige evner sender målet ind i et Rabiat Raseri, hvilket øger deres nærkampsangrebskraft med ", 3, ", men reducerer rustning med ", 4, " i ", 5, ".  Rabiate fjender vil ikke flygte og vil ignorere effekter fra Frygt og Rædsel."},
        {"^You% gain% (.-)%%% increased% damage% for% (.-)% each% time% you% cast% a% spell% from% a% different% school% of% magic%.$", {2}, "Du får ", 1, "% øget skade i ", 2, ", hver gang du besværger en besværgelse fra en anden magiskole."},
        {"^You% gain% (.-)% Energy%.$", {}, "Du får ", 1, " Energi."},
        {"^You% gain% (.-)% energy%.$", {}, "Du får ", 1, " energi."},
        {"^You% gain% (.-)% mana%.$", {}, "Du får ", 1, " mana."},
        {"^You% gain% (.-)%%% of% your% maximum% Health% and% Mana% over% (.-)% each% time% you% deliver% the% killing% blow% to% a% non%-trivial% enemy%.% Ineffective% in% dungeons%,% raids%,% and% battlegrounds%.$", {2}, "Du får ", 1, "% af dit maksimale Liv og Mana over ", 2, " hver gang du leverer dødsstødet til en ikke-triviel fjende. Virkningsløs i fangehuller, togter og slagmarker."},
        {"^You% gain% (.-)% extra% Rage% every% time% you% take% any% damage% or% deal% auto% attack% damage%.$", {}, "Du får ", 1, " ekstra Vrede hver gang du modtager enhver skade eller forvolder autoangrebsskade."},
        {"^You% gain% (.-)% Rage% every% time% you% Parry% or% one% of% your% attacks% is% Parried%.$", {}, "Du får ", 1, " Vrede hver gang du Parerer, eller et af dine angreb bliver Parereret."},
    },
    ["You gene"] = {
        {"^You% generate% (.-)%%% more% threat% for% (.-)% after% using% Distracting% Shot%.$", {2}, "Du genererer ", 1, "% mere trussel i ", 2, " efter brug af Distraherende Skud."},
        {"^You% generate% (.-)%%% more% Rage% from% all% damage% you% deal%.$", {}, "Du genererer ", 1, "% mere Vrede fra al den skade du forvolder."},
    },
    ["You have"] = {
        {"^You% have% a% chance% whenever% you% deal% ranged% damage% to% apply% an% Expose% Weakness% effect% to% the% target%.% Expose% Weakness% increases% the% Ranged% Attack% Power% of% all% attackers% against% that% target% by% (.-)% for% (.-)%.$", {2}, "Du har en chance, hver gang du forvolder distanceskade, for at påføre målet en Blotlæg Svaghed-effekt. Blotlæg Svaghed øger alle angriberes Distance Angrebskraft mod det mål med ", 1, " i ", 2, "."},
        {"^You% have% been% touched% by% energizing% winds%.% Increases% run% speed% by% (.-)%%%.%\n%\nTaking% hostile% action% will% end% this% effect%.$", {}, "Du er blevet berørt af energigivende vinde. Øger løbehastigheden med ", 1, "%.\n\nAt udføre fjendtlig handling vil afslutte denne effekt."},
        {"^You% have% been% slimed%!% % Movement% speed% slowed% (.-)%%%.$", {}, "Du er blevet slimet!  Bevægelseshastigheden bremset med ", 1, "%."},
        {"^You% have% been% slimed%!% % Movement% speed% slowed% (.-)%%%.% % Get% out% before% you%'re% infected%!$", {}, "Du er blevet slimet!  Bevægelseshastigheden bremset med ", 1, "%.  Kom ud herfra, før du bliver smittet!"},
        {"^You% have% a% (.-)%%% chance% to% gain% (.-)% Energy% each% time% you% deal% periodic% Nature% or% Bleed% damage%.$", {}, "Du har en ", 1, "% chance for at få ", 2, " Energi, hver gang du forvolder periodisk Natur- eller blødningsskade."},
        {"^You% have% a% (.-)%%% chance% to% regain% (.-)% mana% any% time% you% take% damage%.$", {}, "Du har en ", 1, "% chance for at genvinde ", 2, " mana, når som helst du modtager skade."},
        {"^You% have% a% (.-)%%% chance% whenever% you% deal% melee% damage% to% reduce% your% victim%'s% Attack% Power% by% (.-)% for% (.-)%.$", {3}, "Du har en ", 1, "% chance, hver gang du forvolder nærkampsskade, for at reducere dit offers Angrebskraft med ", 2, " i ", 3, "."},
        {"^You% have% a% (.-)%%% chance% to% gain% (.-)% Energy% every% time% you% deal% melee% damage% with% your% off%-hand% weapon%.$", {}, "Du har en ", 1, "% chance for at få ", 2, " Energi, hver gang du forvolder nærkampsskade med dit bivåben."},
        {"^You% have% a% (.-)%%% chance% to% avoid% interruption% caused% by% damage% while% casting% Lightning% Bolt%,% Chain% Lightning%,% or% Lava% Burst%,% and% a% (.-)%%% increased% chance% to% trigger% your% Elemental% Focus% talent%.$", {}, "Du har en ", 1, "% chance for at undgå afbrydelse forårsaget af skade, mens du støber Lynbolt, Kædelyn eller Lavaudbrud, samt en ", 2, "% øget chance for at udløse dit Elementar Fokus-talent."},
