    ["You heal"] = {
        {"^You% heal% your% pet% for% (.-)%%% of% all% spell% damage% you% deal%.% When% you% gain% Mana% from% Life% Tap%,% your% summoned% demon% gains% (.-)%%% of% the% Mana% you% gain%.$", {}, "Du heler dit kæledyr for ", 1, "% af al besværgelsesskade, du forvolder. Når du får Mana fra Livstapning, får din fremkaldte dæmon ", 2, "% af den Mana, du får."},
        {"^You% heal% for% (.-)%%% of% all% damage% done% by% your% Corruption%.% This% healing% is% increased% to% (.-)%%% if% the% target% is% also% afflicted% with% your% Drain% Life%.$", {}, "Du heler ", 1, "% af al skade forvoldt af din Fordærvelse. Denne heling øges til ", 2, "%, hvis målet også er ramt af dit Dræn Liv."},
    },
    ["You hurl"] = {
        {"^You% hurl% molten% lava% at% the% target%,% dealing% (.-)% Fire% damage%.% If% your% Flame% Shock% is% on% the% target%,% Lava% Burst% deals% (.-)%%% increased% damage%.$", {}, "Du slynger smeltet lava mod målet og forvolder ", 1, " Ildskade. Hvis din Flammechok er på målet, forvolder Lavaudbrud ", 2, "% øget skade."},
        {"^You% hurl% molten% lava% at% the% target%,% dealing% (.-)% Fire% damage%.% If% your% Flame% Shock% is% on% the% target%,% Lava% Burst% deals% (.-)%%% increased% damage%.$", {}, "Du slynger smeltet lava mod målet og forvolder ", 1, " Ildskade. Hvis din Flammechok er på målet, forvolder Lavaudbrud ", 2, "% øget skade."},
        {"^You% hurl% molten% lava% at% the% target%,% dealing% (.-)% Fire% damage%.% If% your% Flame% Shock% is% on% the% target%,% Lava% Burst% will% deal% a% critical% strike%.$", {}, "Du slynger smeltet lava mod målet og forvolder ", 1, " Ildskade. Hvis din Flammechok er på målet, vil Lavaudbrud forvolde et kritisk angreb."},
        {"^You% hurl% molten% lava% at% the% target%,% dealing% (.-)% to% (.-)% Fire% damage%.% If% your% Flame% Shock% is% on% the% target%,% Lava% Burst% will% deal% a% critical% strike%.$", {}, "Du slynger smeltet lava mod målet og forvolder ", 1, " til ", 2, " Ildskade. Hvis din Flammechok er på målet, vil Lavaudbrud forvolde et kritisk angreb."},
    },
    ["You kill"] = {
        {"^You% killed% another% player%!% %\nMovement% speed% increased% by% (.-)%%% for% (.-)%.$", {2}, "Du dræbte en anden spiller! \nBevægelseshastigheden øget med ", 1, "% i ", 2, "."},
        {"^You% killed% another% player%!% %\nMovement% speed% increased% by% (.-)%%%.$", {}, "Du dræbte en anden spiller! \nBevægelseshastigheden øget med ", 1, "%."},
    },
    ["You may "] = {
        {"^You% may% use% Execute% once% regardless% of% target%'s% health% and% you% will% have% (.-)% Rage% remaining% afterward%.$", {}, "Du må bruge Henrettelse én gang uanset målets helbred, og du vil bagefter have ", 1, " resterende Vrede."},
    },
    ["You rece"] = {
        {"^You% receive% a% (.-)%%% discount% on% all% flight% paths%,% and% your% flight% path% mount% flies% (.-)%%% faster%.$", {}, "Du får ", 1, "% rabat på alle flyveruter, og dit flyveruteridedyr flyver ", 2, "% hurtigere."},
    },
    ["You reco"] = {
        {"^You% recover% an% additional% (.-)%%% of% your% Health% and% Mana% every% 5% sec% while% not% in% combat%.$", {}, "Du genopretter yderligere ", 1, "% af dit Liv og din Mana hvert 5. sek., når du ikke er i kamp."},
    },
    ["You rege"] = {
        {"^You% regenerate% health% equal% to% (.-)%%% of% your% STA% every% (.-)% secs%,% even% while% in% combat%.$", {}, "Du genopretter helbred svarende til ", 1, "% af din UDH hver ", 2, " sek., selv i kamp."},
    },
    ["You reta"] = {
        {"^You% retain% up% to% (.-)%%% of% your% rage% when% you% change% from% Defensive% Stance% to% any% other% stance%.$", {}, "Du beholder op til ", 1, "% af dit raseri, når du skifter fra Forsvarsstilling til enhver anden holdning."},
        {"^You% retain% up% to% (.-)% Rage% when% you% change% Stances%.$", {}, "Du beholder op til ", 1, " Vrede, når du skifter Stilling."},
        {"^You% retain% up% to% (.-)% Rage% when% you% change% Stances%.$", {}, "Du beholder op til ", 1, " Vrede, når du skifter Stilling."},
    },
    ["You summ"] = {
        {"^You% summon% a% flurry% of% stars% from% the% sky% on% all% targets% within% 30% yards% of% the% caster%,% each% dealing% (.-)% Arcane% damage%.% Also% causes% (.-)% Arcane% damage% to% all% other% enemies% within% (.-)% yards% of% the% enemy% target%.% Maximum% 20% stars%.% Lasts% (.-)%.$", {4}, "Du tilkalder en byge af stjerner fra himlen over alle mål inden for 30 meter fra udøveren, hver forvoldende ", 1, " Arkanskade. Forårsager også ", 2, " Arkanskade til alle andre fjender inden for ", 3, " meter fra fjendens mål. Maksimal 20 stjerner. Varer ", 4, "."},
        {"^You% summon% a% flurry% of% stars% from% the% sky% over% (.-)%,% striking% targets% within% (.-)% yards% of% your% location%,% each% dealing% (.-)% to% (.-)% Arcane% damage% to% its% target% and% (.-)% Arcane% damage% to% all% other% enemies% within% (.-)% yards%.% Maximum% 20% stars%.%\n%\nShapeshifting% or% mounting% cancels% the% effect%.% Any% effect% which% causes% you% to% lose% control% of% your% character% will% suppress% the% Starfall% effect%.%\n%\nBenefits% from% and% triggers% most% talents% and% effects% that% trigger% or% benefit% from% Moonfire%.$", {1}, "Du tilkalder en byge af stjerner fra himlen over ", 1, ", som rammer mål inden for ", 2, " meter fra din placering, hver forvoldende ", 3, " til ", 4, " Arkanskade til sit mål og ", 5, " Arkanskade til alle andre fjender inden for ", 6, " meter. Maksimal 20 stjerner.\n\nGestaltskiftende eller opstigning annullerer effekten. Enhver effekt, der får dig til at miste kontrollen over din karakter, undertrykker Stjernefald-effekten.\n\nDrager fordel af og udløser de fleste talenter og effekter, der udløser eller drager fordel af Månebrand."},
    },
    ["You take"] = {
        {"^You% take% on% the% aspects% of% a% beast%,% becoming% untrackable% and% increasing% Melee% Attack% Power% by% (.-)%.% Only% one% Aspect% can% be% active% at% a% time%.$", {}, "Du antager et udyrs aspekter, bliver uopsporlig og øger Nærkampsangrebskraft med ", 1, ". Kun ét Aspekt kan være aktivt ad gangen."},
        {"^You% take% (.-)%%% reduced% damage% while% Holy% Shield% is% active%.$", {}, "Du tager ", 1, "% reduceret skade, mens Hellig Skjold er aktiv."},
        {"^You% take% (.-)%%% less% durability% loss% when% you% die%.$", {}, "Du tager ", 1, "% mindre holdbarhedstab, når du dør."},
        {"^You% take% (.-)%%% reduced% damage% from% Undead% enemies%.$", {}, "Du tager ", 1, "% reduceret skade fra Udøde fjender."},
        {"^You% take% (.-)%%% increased% damage% from% Shrouding% Bolt%.$", {}, "Du tager ", 1, "% øget skade fra Tilslørende Bolt."},
        {"^You% take% (.-)%%% reduced% Physical% damage% while% Blade% Dance% is% active%,% reduced% by% an% additional% 1%%% for% every% (.-)% of% your% Defense% skill% beyond% (.-)%.% Additionally%,% your% chance% to% Dodge% is% multiplied% by% (.-)%%%,% you% have% (.-)%%% reduced% chance% to% be% critically% hit% by% melee% attacks%,% you% deal% (.-)%%% less% damage%,% the% threat% generated% by% all% your% actions% is% massively% increased%,% and% your% Feint% ability% is% replaced% with% Tease%,% which% Taunts% the% target% to% attack% you%.%\n%\n(.-)%\n(.-)$", {}, "Du tager ", 1, "% reduceret fysisk skade, mens Klingedans er aktiv, reduceret med yderligere 1% for hver ", 2, " af din Forsvarsfærdighed ud over ", 3, ". Derudover er din chance for at undvige multipliceret med ", 4, "%, du har ", 5, "% reduceret chance for at blive ramt kritisk af nærkampsangreb, du forvolder ", 6, "% mindre skade, trusslen genereret af alle dine handlinger er massivt øget, og din Finte-evne erstattes af Drille, som provokerer målet til at angribe dig.\n\n", 7, "\n", 8},
    },
    ["You turn"] = {
        {"^You% turn% to% stone%,% protecting% you% from% all% physical% attacks% and% spells% for% (.-)%,% but% during% that% time% you% cannot% attack%,% move% or% cast% spells%.% % You% can% only% have% the% effect% of% one% flask% at% a% time%.$", {1}, "Du forvandles til sten, beskytter dig mod alle fysiske angreb og besværgelser i ", 1, ", men i den tid kan du ikke angribe, bevæge dig eller besværge.  Du kan kun have effekten af én kolbe ad gangen."},
        {"^You% turn% to% stone%,% protecting% you% from% all% physical% attacks% and% spells% for% (.-)%,% but% during% that% time% you% cannot% attack%,% move% or% cast% spells%.% You% can% only% have% the% effect% of% one% flask% at% a% time%.$", {1}, "Du forvandles til sten, beskytter dig mod alle fysiske angreb og besværgelser i ", 1, ", men i den tid kan du ikke angribe, bevæge dig eller besværge. Du kan kun have effekten af én kolbe ad gangen."},
    },
    ["You're o"] = {
        {"^You%'re% on% fire%!% Forced% to% run%,% and% taking% (.-)% fire% damage% every% (.-)% % seconds%.$", {}, "Du er til affyr! Tvunget til at løbe, og tager ", 1, " Ildskade hvert ", 2, "  sekunder."},
    },
    ["You're s"] = {
        {"^You%'re% struggling% for% air%.% Underwater% breath% is% reduced% by% (.-)%%%.$", {}, "Du kæmper for luft. Undervandsånding er reduceret med ", 1, "%."},
