    ["Your Lig"] = {
        {"^Your% Lightning% Bolt% ability% can% now% also% trigger% the% Maelstrom% Weapon% talent%,% but% with% a% (.-)%%% reduced% chance%.$", {}, "Din Lynbolt-evne kan nu også udløse Malstrøm Våben-talentet, men med en ", 1, "% reduceret chance."},
        {"^Your% Lightning% Bolt%,% Chain% Lightning%,% and% Shock% spells% have% a% 20%%% chance% to% grant% up% to% (.-)% Nature% damage% to% spells% for% (.-)%.$", {2}, "Dine Lynbolt-, Kædelyn- og Chok-besværgelser har en 20% chance for at tildele op til ", 1, " Naturskade til besværgelser i ", 2, "."},
        {"^Your% Lightning% Shield% never% loses% charges%,% now% has% a% (.-)% sec% cooldown%,% and% deals% damage% to% all% enemies% within% (.-)% yards%.$", {}, "Dit Lynskjold mister aldrig ladninger, har nu en ", 1, " sek. genopladning og forvolder skade til alle fjender inden for ", 2, " meter."},
