    ["[DNT] Su"] = {
        {"^%[DNT%]% Suffering% (.-)%%% of% your% maximum% health% as% damage% every% (.-)% sec%.$", {}, "[OVERSÆT-IKKE] Lidelse på ", 1, "% af din maksimale livspoint som skade hver ", 2, " sek."},
