    },
    ["[Fuses A"] = {
        {"^%[Fuses% Arcane%,% Fire%,% and% Frost% magic% to% freeze% chronomantic% energy% into% a% stored% state% for% later% use%.% You% can% hold% this% energy% for% up% to% (.-)% before% it% combusts% and% expires%.% When% unleashed%,% heals% a% friendly% target% for% (.-)% to% (.-)%.%\n%\nThis% spell% is% considered% Arcane%,% Fire%,% and% Frost% for% interactions% with% other% spells%,% talents%,% and% effects%.%]$", {1}, "[Lunter Arkan, Ild og Frost magi sammen for at fryse kronomantisk energi ind i en lagret tilstand til senere brug. Du kan holde på denne energi i op til ", 1, ", før den brænder sammen og udløber. Når den løslades, helbreder den et venligt mål for ", 2, " til ", 3, ".\n\nDenne fortryllelse regnes som Arkan, Ild og Frost i samspil med andre fortryllelser, talenter og effekter.]"},
    },
    ["[NYI] Gr"] = {
        {"^%[NYI%]% Grants% you% a% shield% which% absorbs% up% to% (.-)% damage% over% (.-)%.% Fire% damage% is% reduced% by% (.-)%%% while% the% shield% is% active%.$", {2}, "[IKKE-IMPL.] Giver dig et skjold der absorberer op til ", 1, " skade over ", 2, ". Ild-skade reduceres med ", 3, "% mens skjoldet er aktivt."},
    },
    ["|CFFFF20"] = {
        {"^%|CFFFF2020Requires% Bear% Form%,% Dire% Bear% Form%|R%\nCharge% an% enemy%,% immobilizing% them% and% interrupting% any% spell% they% are% casting% for% (.-)%.%\n%\n(.-)$", {1}, "|CFFFF2020Kræver Bjørneform, Frygtindgydende Bjørneform|R\nLad din Ladning løs på en fjende, immobiliser dem og afbryd enhver fortryllelse, de forsøger at kaste, i ", 1, ".\n\n", 2},
        {"^%|CFFFF2020Requires% Cat% Form%,% Bear% Form%,% Dire% Bear% Form%|R%\nCauses% your% Primal% Bite% ability% to% strike% up% to% (.-)% targets%,% removes% its% cooldown%,% and% increases% the% critical% strike% chance% of% your% Combo% Point%-generating% abilities% by% (.-)%%%.% Clears% and% grants% immunity% to% Fear% effects% for% the% duration%.% Lasts% (.-)%.$", {3}, "|CFFFF2020Kræver Katteform, Bjørneform, Frygtindgydende Bjørneform|R\nGør at dit Urtids-Bid rammer op til ", 1, " mål, fjerner dets genopladning og øger den kritiske slagchance for dine kombopeg-genererende evner med ", 2, "%. Rydder og giver immunitet over for Frygt-effekter i varigheden. Varer ", 3, "."},
        {"^%|CFFFF2020Requires% Cat% Form%|R%\nFinishing% move% that% increases% Physical% damage% done% by% (.-)%%% while% in% Cat% Form%.% % Lasts% longer% per% combo% point%:%\n% % % 1% point% % %:% (.-)% seconds%\n% % % 2% points%:% (.-)% seconds%\n% % % 3% points%:% (.-)% seconds%\n% % % 4% points%:% (.-)% seconds%\n% % % 5% points%:% (.-)% seconds$", {}, "|CFFFF2020Kræver Katteform|R\nAfslutningstræk, der øger fysisk skade forvoldt med ", 1, "%, mens du er i Katteform.  Varer længere pr. kombopeg:\n   1 peg  : ", 2, " sekunder\n   2 peg: ", 3, " sekunder\n   3 peg: ", 4, " sekunder\n   4 peg: ", 5, " sekunder\n   5 peg: ", 6, " sekunder"},
        {"^%|CFFFF2020Requires% Cat% Form%|R%\nIncreases% Physical% damage% done% by% (.-)%%% for% (.-)%,% and% instantly% grants% (.-)% Energy%.$", {2}, "|CFFFF2020Kræver Katteform|R\nØger fysisk skade forvoldt med ", 1, "% i ", 2, ", og giver øjeblikkeligt ", 3, " Energi."},
        {"^%|CFFFF2020Requires% Cat% Form%|R%\nIncreases% Physical% damage% done% by% (.-)%%% for% (.-)%.$", {2}, "|CFFFF2020Kræver Katteform|R\nØger fysisk skade forvoldt med ", 1, "% i ", 2, "."},
    },
    ["|CFFFFFF"] = {
        {"^%|CFFFFFFFFRequires% Bear% Form%,% Dire% Bear% Form%|R%\nCharge% an% enemy%,% immobilizing% them% and% interrupting% any% spell% they% are% casting% for% (.-)%.%\n%\n(.-)$", {1}, "|CFFFFFFFFKræver Bjørneform, Frygtindgydende Bjørneform|R\nLad din Ladning løs på en fjende, immobiliser dem og afbryd enhver fortryllelse, de forsøger at kaste, i ", 1, ".\n\n", 2},
        {"^%|CFFFFFFFFReuires% Cat% Form%,% Bear% Form%,% Dire% Bear% Form%|R%\nCauses% your% Primal% Bite% ability% to% strike% up% to% (.-)% targets%,% removes% its% cooldown%,% and% increases% the% critical% strike% chance% of% your% Combo% Point%-generating% abilities% by% (.-)%%%.% Clears% and% grants% immunity% to% Fear% effects% for% the% duration%.% Lasts% (.-)%.$", {3}, "|CFFFFFFFFKræver Katteform, Bjørneform, Frygtindgydende Bjørneform|R\nGør at dit Urtids-Bid rammer op til ", 1, " mål, fjerner dets genopladning og øger den kritiske slagchance for dine kombopeg-genererende evner med ", 2, "%. Rydder og giver immunitet over for Frygt-effekter i varigheden. Varer ", 3, "."},
        {"^%|CFFFFFFFFRequires% Cat% Form%|R%\nFinishing% move% that% increases% Physical% damage% done% by% (.-)%%% while% in% Cat% Form%.% % Lasts% longer% per% combo% point%:%\n% % % 1% point% % %:% (.-)% seconds%\n% % % 2% points%:% (.-)% seconds%\n% % % 3% points%:% (.-)% seconds%\n% % % 4% points%:% (.-)% seconds%\n% % % 5% points%:% (.-)% seconds$", {}, "|CFFFFFFFFKræver Katteform|R\nAfslutningstræk, der øger fysisk skade forvoldt med ", 1, "%, mens du er i Katteform.  Varer længere pr. kombopeg:\n   1 peg  : ", 2, " sekunder\n   2 peg: ", 3, " sekunder\n   3 peg: ", 4, " sekunder\n   4 peg: ", 5, " sekunder\n   5 peg: ", 6, " sekunder"},
        {"^%|CFFFFFFFFRequires% Cat% Form%|R%\nIncreases% Physical% damage% done% by% (.-)%%% for% (.-)%,% and% instantly% grants% (.-)% Energy%.$", {2}, "|CFFFFFFFFKræver Katteform|R\nØger fysisk skade forvoldt med ", 1, "% i ", 2, ", og giver øjeblikkeligt ", 3, " Energi."},
        {"^%|CFFFFFFFFRequires% Cat% Form%|R%\nIncreases% Physical% damage% done% by% (.-)%%% for% (.-)%.$", {2}, "|CFFFFFFFFKræver Katteform|R\nØger fysisk skade forvoldt med ", 1, "% i ", 2, "."},
